    }

    func testBackgroundSuspendedFallsBackToContactStatus() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: nil,
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .backgroundSuspended),
            isNetworkPathSatisfied: true,
            fallbackStatus: "Last seen recently"
        )

        XCTAssertEqual(text, "Last seen recently")
    }

    func testActionTextHasPriorityOverConnectionState() {
        let text = ChatConnectionStatusTextPolicy.text(
            actionText: "typing...",
            isAccountConnecting: true,
            sendReadinessSnapshot: snapshot(phase: .binding),
            isNetworkPathSatisfied: false,
            fallbackStatus: "Online"
        )

        XCTAssertEqual(text, "typing...")
    }

    private func snapshot(phase: AccountSendReadinessPhase) -> AccountSendReadinessSnapshot {
        AccountSendReadinessSnapshot(
            phase: phase,
            updatedAt: Date(timeIntervalSince1970: 0),
            reason: nil
        )
    }
}

final class AccountSendCoordinatorTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "AccountSendCoordinatorTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testQueuedMessageDoesNotFlushBeforeSendReady() throws {
        var isReady = false
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        XCTAssertTrue(recorder.sentMessages.isEmpty)

        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])
    }

    func testQueuedRegularMessageCanonicalizesFullDestinationJidToBareWhenSent() throws {
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { true }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(
            opponent: "romeo@example.com",
            stanzaTo: "romeo@example.com/iPhone",
            originId: "message-1"
        ))

        let message = try XCTUnwrap(recorder.sentMessages.first)
        XCTAssertEqual(message.to?.bare, "romeo@example.com")
        XCTAssertNil(message.to?.resource)
    }

    func testPerChatOrderingWaitsForReceiptBeforeNextSend() throws {
        let isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1", createdAt: Date(timeIntervalSince1970: 1)))
        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-2", createdAt: Date(timeIntervalSince1970: 2)))

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])

        coordinator.deliveryReceiptReceived(originId: "message-1", stanzaId: "archive-1")

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-2"])
    }

    func testSuccessfulResumeDoesNotDuplicateAwaitingReceiptMessage() throws {
        var isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))
        XCTAssertEqual(recorder.sentMessages.count, 1)

        isReady = false
        coordinator.streamDidDisconnect(canResume: true)
        isReady = true
        coordinator.streamManagementResumeSucceeded()

        XCTAssertEqual(recorder.sentMessages.count, 1)
    }

    func testFullReconnectReplaysWithSameOriginIdAndRetryMarkup() throws {
        var isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        isReady = false
        coordinator.streamDidDisconnect(canResume: true)
        coordinator.streamManagementResumeFailed()
        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-1"])
        XCTAssertNotNil(recorder.sentMessages.last?.element(forName: "retry", xmlns: "https://xabber.com/protocol/delivery"))
        XCTAssertEqual(
            recorder.sentMessages.last?.element(forName: "origin-id", xmlns: "urn:xmpp:sid:0")?.attributeStringValue(forName: "id"),
            "message-1"
        )
    }

    func testServerErrorMarksQueueTerminalAndStopsRetry() throws {
        let isReady = true
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))
        coordinator.terminalFailure(originId: "message-1", error: "Forbidden")
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.count, 1)
        let realm = try WRealm.safe()
        let item = try XCTUnwrap(realm.objects(OutgoingMessageQueueItem.self).first)
        XCTAssertEqual(item.state, .terminalFailed)
        XCTAssertEqual(item.lastError, "Forbidden")
    }

    func testMessageManagerInitPreservesRecoverablePendingSend() throws {
        let owner = "owner@example.com"
        let message = try storeRecoverableMessage(owner: owner, originId: "pending-1")

        let manager = MessageManager(withOwner: owner, activeStream: true)
        manager.updateSendingMessagesTimer?.invalidate()
        manager.updateSendingMessagesTimer = nil

        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: message.primary))
        XCTAssertEqual(stored.state, .sending)
        XCTAssertNil(stored.messageError)
        XCTAssertEqual(realm.objects(OutgoingMessageQueueItem.self).filter("messagePrimary == %@", message.primary).count, 1)
    }

    func testSendSimpleMessagePersistsSendingStateAndDurableQueueSynchronously() throws {
        let owner = "owner@example.com"
        let manager = MessageManager(withOwner: owner, activeStream: true)
        defer {
            manager.updateSendingMessagesTimer?.invalidate()
            manager.updateSendingMessagesTimer = nil
        }

        let originId = manager.sendSimpleMessage(
            "Hello",
            to: "romeo@example.com",
            forwarded: [],
            conversationType: .regular
        )

        let realm = try WRealm.safe()
        let message = try XCTUnwrap(realm.object(
            ofType: MessageStorageItem.self,
            forPrimaryKey: MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        ))
        XCTAssertEqual(message.state, .sending)
        XCTAssertEqual(message.body, "Hello")
        XCTAssertEqual(
            realm.objects(OutgoingMessageQueueItem.self)
                .filter("owner == %@ AND originId == %@", owner, originId)
                .count,
            1
        )
    }

    func testQueuedMessageDoesNotFlushWhileSuspectedStaleAndFlushesAfterReady() throws {
        var isReady = false
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = makeCoordinator(isReady: { isReady }, recorder: recorder)

        try coordinator.enqueueRegularMessage(makeRequest(originId: "message-1"))

        XCTAssertTrue(recorder.sentMessages.isEmpty)

        isReady = true
        coordinator.accountDidBecomeSendReady()

        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1"])
    }

    private func makeCoordinator(
        owner: String = "owner@example.com",
        isReady: @escaping () -> Bool,
        recorder: AccountSendCoordinatorRecorder
    ) -> AccountSendCoordinator {
        AccountSendCoordinator(
            environment: AccountSendCoordinator.Environment(
                owner: owner,
                isSendReady: isReady,
                decorateMessage: { message, retry, missRetryElement in
                    if retry && !missRetryElement {
                        message.addChild(DDXMLElement(name: "retry", xmlns: "https://xabber.com/protocol/delivery"))
                    }
                    return message
                },
                sendMessage: { message in
                    recorder.sentMessages.append(message.copy() as! XMPPMessage)
                },
                log: { _, _ in }
            )
        )
    }

    private func makeRequest(
        owner: String = "owner@example.com",
        opponent: String = "romeo@example.com",
        stanzaTo: String? = nil,
        originId: String,
        createdAt: Date = Date(timeIntervalSince1970: 1)
    ) -> AccountQueuedMessageSendRequest {
        let stanzaTo = stanzaTo ?? opponent
        return AccountQueuedMessageSendRequest(
            owner: owner,
            conversationJid: opponent,
            conversationType: .regular,
            messagePrimary: MessageStorageItem.genPrimary(messageId: originId, owner: owner),
            originId: originId,
            stanzaXML: """
            <message type='chat' to='\(stanzaTo)' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            createdAt: createdAt,
            replayRequired: false
        )
    }

    @discardableResult
    private func storeRecoverableMessage(owner: String, originId: String) throws -> MessageStorageItem {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.owner = owner
        message.opponent = "romeo@example.com"
        message.outgoing = true
        message.messageId = originId
        message.primary = MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        message.conversationType = .regular
        message.displayAs = .text
        message.body = "Hello"
        message.legacyBody = "Hello"
        message.state = .sending
        message.date = Date(timeIntervalSince1970: 1)
        message.sentDate = message.date

        let stanza = MessageStanzaStorageItem()
        stanza.set(
            originId,
            for: owner,
            with: """
            <message type='chat' to='romeo@example.com' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            at: message.date,
            primary: message.primary
        )

        try realm.write {
            realm.add(message, update: .modified)
            realm.add(stanza, update: .modified)
        }
        return message
    }
}

private final class AccountSendCoordinatorRecorder {
    var sentMessages: [XMPPMessage] = []
}

final class ReliableMessageDeliveryReceiptProcessorTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "ReliableMessageDeliveryReceiptProcessorTests-\(name)-\(UUID().uuidString)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testReceiptAppliesMessageStateAndAdvancesOutgoingQueue() throws {
        let owner = "owner@example.com"
        let recorder = AccountSendCoordinatorRecorder()
        let coordinator = AccountSendCoordinator(
            environment: AccountSendCoordinator.Environment(
                owner: owner,
                isSendReady: { true },
                decorateMessage: { message, _, _ in message },
                sendMessage: { message in
                    recorder.sentMessages.append(message.copy() as! XMPPMessage)
                },
                log: { _, _ in }
            )
        )
        try storeSendingMessage(owner: owner, originId: "message-1")
        try storeSendingMessage(owner: owner, originId: "message-2")
        try coordinator.enqueueRegularMessage(makeRequest(owner: owner, originId: "message-1", createdAt: Date(timeIntervalSince1970: 1)))
        try coordinator.enqueueRegularMessage(makeRequest(owner: owner, originId: "message-2", createdAt: Date(timeIntervalSince1970: 2)))

        let receipt = XabberDeliveryReceipt(
            originId: "message-1",
            stanzaId: "archive-1",
            stamp: Date(timeIntervalSince1970: 100)
        )
        let applied = ReliableMessageDeliveryReceiptProcessor.apply(owner: owner, receipt: receipt) { originId, stanzaId in
            coordinator.deliveryReceiptReceived(originId: originId, stanzaId: stanzaId)
        }

        XCTAssertTrue(applied)
        XCTAssertEqual(recorder.sentMessages.map(\.elementID), ["message-1", "message-2"])

        let realm = try WRealm.safe()
        let stored = try XCTUnwrap(realm.object(
            ofType: MessageStorageItem.self,
            forPrimaryKey: MessageStorageItem.genPrimary(messageId: "message-1", owner: owner)
        ))
        XCTAssertEqual(stored.state, .sended)
        XCTAssertEqual(stored.archivedId, "archive-1")
        XCTAssertEqual(stored.date, Date(timeIntervalSince1970: 100))
        XCTAssertEqual(
            realm.objects(OutgoingMessageQueueItem.self)
                .filter("owner == %@ AND originId == %@", owner, "message-1")
                .count,
            0
        )
    }

    private func makeRequest(
        owner: String,
        opponent: String = "romeo@example.com",
        originId: String,
        createdAt: Date
    ) -> AccountQueuedMessageSendRequest {
        AccountQueuedMessageSendRequest(
            owner: owner,
            conversationJid: opponent,
            conversationType: .regular,
            messagePrimary: MessageStorageItem.genPrimary(messageId: originId, owner: owner),
            originId: originId,
            stanzaXML: """
            <message type='chat' to='\(opponent)' id='\(originId)' from='\(owner)'>
              <body>Hello</body>
              <origin-id xmlns='urn:xmpp:sid:0' id='\(originId)'/>
            </message>
            """,
            createdAt: createdAt,
            replayRequired: false
        )
    }

    private func storeSendingMessage(owner: String, originId: String) throws {
        let realm = try WRealm.safe()
        let message = MessageStorageItem()
        message.owner = owner
        message.opponent = "romeo@example.com"
        message.outgoing = true
        message.messageId = originId
        message.primary = MessageStorageItem.genPrimary(messageId: originId, owner: owner)
        message.conversationType = .regular
        message.displayAs = .text
        message.body = "Hello"
        message.legacyBody = "Hello"
        message.state = .sending
        message.date = Date(timeIntervalSince1970: 1)
        message.sentDate = message.date

        try realm.write {
            realm.add(message, update: .modified)
        }
    }
}

final class AccountStreamLifecycleGateTests: XCTestCase {

    func testDuplicateConnectIsSkippedWhileConnecting() {
        let gate = AccountStreamLifecycleGate()

        let first = gate.beginConnect(trigger: .addExistingAccount)
        let second = gate.beginConnect(trigger: .restore)

        guard case .start(let attemptID) = first else {
            XCTFail("Expected first connect to start")
            return
        }

        XCTAssertEqual(second, .skip(phase: .connecting, activeAttemptID: attemptID))
        XCTAssertEqual(gate.snapshot().phase, .connecting)
        XCTAssertEqual(gate.snapshot().activeAttemptID, attemptID)
    }

    func testTimeoutRetryRequiresActiveConnectingAttempt() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        XCTAssertTrue(gate.canRetryTimeout(for: attemptID))
        XCTAssertFalse(gate.canRetryTimeout(for: attemptID + 1))

        gate.markAuthenticating()

        XCTAssertFalse(gate.canRetryTimeout(for: attemptID))
    }

    func testPostAuthSetupBlocksNewPrimaryConnect() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        gate.markAuthenticating()
        gate.markBinding()
        gate.markPostAuthSetup()

        XCTAssertEqual(
            gate.beginConnect(trigger: .statusUpdate),
            .skip(phase: .postAuthSetup, activeAttemptID: attemptID)
        )
    }

    func testOnlineBlocksRestoreUntilExplicitDisconnect() {
        let gate = AccountStreamLifecycleGate()

        guard case .start = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        gate.markAuthenticating()
        gate.markPostAuthSetup()
        gate.markOnline()

        guard case .skip(phase: .online, activeAttemptID: let onlineAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected online stream to skip restore")
            return
        }

        XCTAssertNotNil(onlineAttemptID)

        gate.markDisconnecting()
        gate.markDisconnected()

        guard case .start(let newAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected restore after disconnect to start")
            return
        }

        XCTAssertNotEqual(onlineAttemptID, newAttemptID)
    }

    func testDisconnectedFrameworkStateClearsBlockedConnectGate() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let firstAttemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected initial connect to start")
            return
        }

        XCTAssertEqual(gate.beginConnect(trigger: .restore), .skip(phase: .connecting, activeAttemptID: firstAttemptID))
        XCTAssertEqual(gate.resetIfBlockedByDisconnectedStream(), .connecting)
        XCTAssertEqual(gate.snapshot().phase, .idle)
        XCTAssertNil(gate.snapshot().activeAttemptID)

        guard case .start(let restoreAttemptID) = gate.beginConnect(trigger: .restore) else {
            XCTFail("Expected restore to start after disconnected stream reset")
            return
        }

        XCTAssertNotEqual(firstAttemptID, restoreAttemptID)
    }

    func testDeviceReregisterForceCreatesFreshAttempt() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let firstAttemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        let forced = gate.beginConnect(trigger: .deviceReregister, force: true)

        guard case .start(let forcedAttemptID) = forced else {
            XCTFail("Expected forced device re-register connect to start")
            return
        }

        XCTAssertNotEqual(firstAttemptID, forcedAttemptID)
        XCTAssertEqual(gate.snapshot().phase, .connecting)
        XCTAssertEqual(gate.snapshot().activeAttemptID, forcedAttemptID)
    }

    func testUIActionStreamConnectsAreSerializedBySameGate() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let attemptID) = gate.beginConnect(trigger: .uiActionOpen) else {
            XCTFail("Expected UI action stream to start")
            return
        }

        XCTAssertEqual(
            gate.beginConnect(trigger: .uiActionPerformRequest),
            .skip(phase: .connecting, activeAttemptID: attemptID)
        )

        gate.markAuthenticating()
        gate.markOnline()

        XCTAssertEqual(
            gate.beginConnect(trigger: .uiActionRestore),
            .skip(phase: .online, activeAttemptID: attemptID)
        )
    }
}

final class VCardLazyLoadScheduleStateTests: XCTestCase {
    func testConcurrentReservationsDeduplicateMissingJids() {
        let state = VCardLazyLoadScheduleState()
        let rosterJids = Set((0..<100).map { "user\($0)@example.com" })
        let storedVCardJids = Set((0..<10).map { "user\($0)@example.com" })
        let expectedJids = rosterJids.subtracting(storedVCardJids)
        let queue = DispatchQueue.global(qos: .userInitiated)
        let group = DispatchGroup()
        let resultLock = NSLock()
        var reservedJids: [String] = []

        for _ in 0..<50 {
            group.enter()
            queue.async {
                let reserved = state.reserveMissingJids(
                    rosterJids: rosterJids,
                    storedVCardJids: storedVCardJids
                )
                resultLock.lock()
                reservedJids.append(contentsOf: reserved)
                resultLock.unlock()
                group.leave()
            }
        }

        XCTAssertEqual(group.wait(timeout: .now() + 2), .success)
        XCTAssertEqual(Set(reservedJids), expectedJids)
        XCTAssertEqual(reservedJids.count, expectedJids.count)
        expectedJids.forEach { jid in
            XCTAssertTrue(state.contains(jid))
        }
    }

    func testReleaseAllowsMissingJidToBeReservedAgain() {
        let state = VCardLazyLoadScheduleState()
        let rosterJids: Set<String> = ["alice@example.com"]
        let storedVCardJids = Set<String>()

        XCTAssertEqual(
            state.reserveFirstMissingJid(rosterJids: rosterJids, storedVCardJids: storedVCardJids),
            "alice@example.com"
        )
        XCTAssertTrue(state.contains("alice@example.com"))

        state.release("alice@example.com")

        XCTAssertFalse(state.contains("alice@example.com"))
        XCTAssertEqual(
            state.reserveFirstMissingJid(rosterJids: rosterJids, storedVCardJids: storedVCardJids),
            "alice@example.com"
        )
    }

    func testStoredVCardJidsAreExcludedFromReservation() {
        let state = VCardLazyLoadScheduleState()
        let rosterJids: Set<String> = ["alice@example.com", "bob@example.com"]
        let storedVCardJids: Set<String> = ["bob@example.com"]

        XCTAssertEqual(
            state.reserveMissingJids(rosterJids: rosterJids, storedVCardJids: storedVCardJids),
            ["alice@example.com"]
        )
        XCTAssertTrue(state.contains("alice@example.com"))
        XCTAssertFalse(state.contains("bob@example.com"))
    }
}

final class AccountXMPPTaskSchedulerTests: XCTestCase {
    func testRunsQueuedTasksByPriority() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        var events: [String] = []
        let completed = expectation(description: "all tasks completed")
        completed.expectedFulfillmentCount = 4

        scheduler.enqueue(priority: .idle, resource: .other("test"), deduplicationKey: "idle") { finish in
            events.append("idle")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .background, resource: .other("test"), deduplicationKey: "background") { finish in
            events.append("background")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .foreground, resource: .other("test"), deduplicationKey: "foreground") { finish in
            events.append("foreground")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .interactive, resource: .other("test"), deduplicationKey: "interactive") { finish in
            events.append("interactive")
            completed.fulfill()
            finish()
        }

        scheduler.resume()

        wait(for: [completed], timeout: 1)
        XCTAssertEqual(events, ["interactive", "foreground", "background", "idle"])
    }

    func testMamArchiveTasksAreMutuallyExclusive() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first MAM task started")
        let secondDidNotStartEarly = expectation(description: "second MAM task did not start early")
        secondDidNotStartEarly.isInverted = true
        let secondStarted = expectation(description: "second MAM task started after first completion")
        var finishFirst: (() -> Void)?
        var isCheckingEarlyStart = true

        scheduler.enqueue(priority: .background, resource: .mamArchive, deduplicationKey: "first") { finish in
            finishFirst = finish
            firstStarted.fulfill()
        }
        scheduler.enqueue(priority: .foreground, resource: .mamArchive, deduplicationKey: "second") { finish in
            if isCheckingEarlyStart {
                secondDidNotStartEarly.fulfill()
            }
            secondStarted.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        wait(for: [secondDidNotStartEarly], timeout: 0.1)
        isCheckingEarlyStart = false
        finishFirst?()
        wait(for: [secondStarted], timeout: 1)
    }

    func testCooldownDelaysNextTaskForSameResource() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0, cooldowns: [.vcard: 0.15])
        )
        let firstStarted = expectation(description: "first vCard task started")
        let secondDidNotStartDuringCooldown = expectation(description: "second vCard task waits for cooldown")
        secondDidNotStartDuringCooldown.isInverted = true
        let secondStarted = expectation(description: "second vCard task started after cooldown")
        var isCheckingCooldown = true

        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "first") { finish in
            firstStarted.fulfill()
            finish()
        }
        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "second") { finish in
            if isCheckingCooldown {
                secondDidNotStartDuringCooldown.fulfill()
            }
            secondStarted.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        wait(for: [secondDidNotStartDuringCooldown], timeout: 0.05)
        isCheckingCooldown = false
        wait(for: [secondStarted], timeout: 1)
    }

    func testResetClearsPendingTasks() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first task started")
        let pendingDidNotStart = expectation(description: "pending task was cancelled")
        pendingDidNotStart.isInverted = true
        var finishFirst: (() -> Void)?

        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "first") { finish in
            finishFirst = finish
            firstStarted.fulfill()
        }
        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "second") { finish in
            pendingDidNotStart.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        scheduler.reset()
        finishFirst?()
        wait(for: [pendingDidNotStart], timeout: 0.1)
    }

    func testDeduplicatedPendingTaskIsPromotedToHigherPriority() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        var events: [String] = []
        let completed = expectation(description: "promoted task completed")

        scheduler.enqueue(priority: .background, resource: .vcard, deduplicationKey: "vcard:alice") { finish in
            events.append("background")
            finish()
        }
        scheduler.enqueue(priority: .foreground, resource: .vcard, deduplicationKey: "vcard:alice") { finish in
            events.append("foreground")
            completed.fulfill()
            finish()
        }

        scheduler.resume()

        wait(for: [completed], timeout: 1)
        XCTAssertEqual(events, ["foreground"])
    }

    func testDuplicateSnapshotRepairKeyCoalescesPendingTask() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        var events: [String] = []
        let completed = expectation(description: "snapshot repair completed")

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("first")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("duplicate")
            finish()
        }

        scheduler.resume()

        wait(for: [completed], timeout: 1)
        XCTAssertEqual(events, ["first"])
    }

    func testDuplicateSnapshotRepairKeyDoesNotQueueWhileRunning() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first snapshot repair started")
        let duplicateStarted = expectation(description: "duplicate snapshot repair should not start")
        duplicateStarted.isInverted = true
        var finishFirst: (() -> Void)?
        var events: [String] = []

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("first")
            finishFirst = finish
            firstStarted.fulfill()
        }

        wait(for: [firstStarted], timeout: 1)

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("duplicate")
            duplicateStarted.fulfill()
            finish()
        }

        finishFirst?()
        wait(for: [duplicateStarted], timeout: 0.1)
        XCTAssertEqual(events, ["first"])
    }

    func testInteractiveMamTaskOutranksBackgroundSnapshotRepair() {
        let scheduler = AccountXMPPTaskScheduler(
            configuration: .test(defaultCooldown: 0),
            startsImmediately: false
        )
        var events: [String] = []
        let completed = expectation(description: "both MAM tasks completed")
        completed.expectedFulfillmentCount = 2

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("snapshot-repair")
            completed.fulfill()
            finish()
        }
        scheduler.enqueue(
            priority: .interactive,
            resource: .mamArchive,
            deduplicationKey: "interactive-open.owner@example.com.romeo@example.com.urn:xabber:chat"
        ) { finish in
            events.append("interactive-open")
            completed.fulfill()
            finish()
        }

        scheduler.resume()

        wait(for: [completed], timeout: 1)
        XCTAssertEqual(events, ["interactive-open", "snapshot-repair"])
    }

    func testInteractiveMamTaskWaitsForCurrentIdleThenRunsBeforeNextIdle() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let currentIdleStarted = expectation(description: "current idle started")
        let interactiveStarted = expectation(description: "interactive started")
        let nextIdleStarted = expectation(description: "next idle started")
        let nextIdleDidNotStartEarly = expectation(description: "next idle waits behind interactive")
        nextIdleDidNotStartEarly.isInverted = true
        var finishCurrentIdle: (() -> Void)?
        var events: [String] = []
        var isCheckingEarlyNextIdle = true

        scheduler.enqueue(
            priority: .idle,
            resource: .mamArchive,
            deduplicationKey: "regular.idle-bootstrap.owner"
        ) { finish in
            events.append("current-idle")
            finishCurrentIdle = finish
            currentIdleStarted.fulfill()
        }

        wait(for: [currentIdleStarted], timeout: 1)

        scheduler.enqueue(
            priority: .idle,
            resource: .mamArchive,
            deduplicationKey: "regular.idle-bootstrap.owner.next"
        ) { finish in
            if isCheckingEarlyNextIdle {
                nextIdleDidNotStartEarly.fulfill()
            }
            events.append("next-idle")
            nextIdleStarted.fulfill()
            finish()
        }
        scheduler.enqueue(
            priority: .interactive,
            resource: .mamArchive,
            deduplicationKey: "chat.interactive-history.MAM next history: test"
        ) { finish in
            events.append("interactive")
            interactiveStarted.fulfill()
            finish()
        }

        wait(for: [nextIdleDidNotStartEarly], timeout: 0.1)
        isCheckingEarlyNextIdle = false
        finishCurrentIdle?()

        wait(for: [interactiveStarted, nextIdleStarted], timeout: 1)
        XCTAssertEqual(events, ["current-idle", "interactive", "next-idle"])
    }

    func testSnapshotRepairsForTwoDialogsUseMamLaneSequentially() {
        let scheduler = AccountXMPPTaskScheduler(configuration: .test(defaultCooldown: 0))
        let firstStarted = expectation(description: "first repair started")
        let secondDidNotStartEarly = expectation(description: "second repair waits")
        secondDidNotStartEarly.isInverted = true
        let secondStarted = expectation(description: "second repair started after first")
        var finishFirst: (() -> Void)?
        var checkingEarlyStart = true

        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.first@example.com.urn:xabber:chat"
        ) { finish in
            finishFirst = finish
            firstStarted.fulfill()
        }
        scheduler.enqueue(
            priority: .background,
            resource: .mamArchive,
            deduplicationKey: "snapshot-repair.owner@example.com.second@example.com.urn:xabber:chat"
        ) { finish in
            if checkingEarlyStart {
                secondDidNotStartEarly.fulfill()
            }
            secondStarted.fulfill()
            finish()
        }

        wait(for: [firstStarted], timeout: 1)
        wait(for: [secondDidNotStartEarly], timeout: 0.1)
        checkingEarlyStart = false
        finishFirst?()
        wait(for: [secondStarted], timeout: 1)
    }
}

final class XMPPUIActionLifecycleCoordinatorTests: XCTestCase {

    func testDuplicateSameOwnerOpenIsSkippedWhileActive() {
        let coordinator = XMPPUIActionLifecycleCoordinator()
        let owner = "alice@example.com"

        guard case .start(let firstStart) = coordinator.beginOpen(owner: owner) else {
            XCTFail("Expected first UI action open to start")
            return
        }

        XCTAssertEqual(
            coordinator.beginOpen(owner: owner, activePhase: .connecting),
            .skipActive(owner: owner, phase: .connecting, activeAttemptID: firstStart.attemptID)
        )

        coordinator.markAuthenticating()

        XCTAssertEqual(
            coordinator.beginOpen(owner: owner, activePhase: .authenticating),
            .skipActive(owner: owner, phase: .authenticating, activeAttemptID: firstStart.attemptID)
        )

        coordinator.markOnline()

        XCTAssertEqual(
            coordinator.beginOpen(owner: owner, activePhase: .online),
            .skipActive(owner: owner, phase: .online, activeAttemptID: firstStart.attemptID)
        )
    }

    func testPerformRequestWaitsForExistingSameOwnerAttempt() {
        let coordinator = XMPPUIActionLifecycleCoordinator()
        let owner = "alice@example.com"

        guard case .start(let start) = coordinator.beginOpen(owner: owner) else {
            XCTFail("Expected first UI action open to start")
            return
        }

        let decision = coordinator.beginPerformRequest(
            owner: owner,
            activePhase: .connecting,
            isAuthenticated: false,
            streamIsDisconnected: false
        )

        XCTAssertEqual(
            decision,
            .waiting(owner: owner, phase: .connecting, activeAttemptID: start.attemptID)
        )
    }

    func testPerformRequestStartsFreshAttemptWhenSameOwnerGateIsStaleAndStreamDisconnected() {
        let coordinator = XMPPUIActionLifecycleCoordinator()
        let owner = "alice@example.com"

        guard case .start(let firstStart) = coordinator.beginOpen(owner: owner) else {
            XCTFail("Expected first UI action open to start")
            return
        }

        let decision = coordinator.beginPerformRequest(
            owner: owner,
            activePhase: nil,
            isAuthenticated: false,
            streamIsDisconnected: true
        )

        guard case .start(let secondStart) = decision else {
            XCTFail("Expected disconnected stale UI action gate to start a fresh attempt")
            return
        }

        XCTAssertEqual(secondStart.owner, owner)
        XCTAssertNotEqual(secondStart.attemptID, firstStart.attemptID)
        XCTAssertNil(secondStart.previousOwner)
    }

    func testStalePreparedConnectIsIgnoredAfterOwnerSwitch() {
        let coordinator = XMPPUIActionLifecycleCoordinator()

        guard case .start(let firstStart) = coordinator.beginOpen(owner: "alice@example.com") else {
            XCTFail("Expected first UI action open to start")
            return
        }

        guard case .start(let secondStart) = coordinator.beginOpen(owner: "bob@example.com") else {
            XCTFail("Expected owner switch to start a new UI action attempt")
            return
        }

        XCTAssertEqual(secondStart.previousOwner, "alice@example.com")
        XCTAssertEqual(
            coordinator.validatePreparedConnect(
                owner: "alice@example.com",
                attemptID: firstStart.attemptID,
                jidBare: "alice@example.com",
                resource: "\(AccountManager.defaultResource)_ui_upgrade_task"
            ),
            .staleAttempt
        )
        XCTAssertEqual(
            coordinator.validatePreparedConnect(
                owner: "bob@example.com",
                attemptID: secondStart.attemptID,
                jidBare: "bob@example.com",
                resource: "\(AccountManager.defaultResource)_ui_upgrade_task"
            ),
            .proceed
        )
    }

    func testPreparedConnectRequiresConfiguredJIDAndUIActionResource() {
        let coordinator = XMPPUIActionLifecycleCoordinator()
        let owner = "alice@example.com"

        guard case .start(let start) = coordinator.beginOpen(owner: owner) else {
            XCTFail("Expected first UI action open to start")
            return
        }

        XCTAssertEqual(
            coordinator.validatePreparedConnect(
                owner: owner,
                attemptID: start.attemptID,
                jidBare: nil,
                resource: nil
            ),
            .missingJID
        )
        XCTAssertEqual(
            coordinator.validatePreparedConnect(
                owner: owner,
                attemptID: start.attemptID,
                jidBare: owner,
                resource: nil
            ),
            .missingJID
        )
        XCTAssertEqual(
            coordinator.validatePreparedConnect(
                owner: owner,
                attemptID: start.attemptID,
                jidBare: owner,
                resource: AccountManager.defaultResource
            ),
            .missingJID
        )
    }

    func testOwnerSwitchStartsOneFreshAttemptAndThenSkipsDuplicate() {
        let coordinator = XMPPUIActionLifecycleCoordinator()

        guard case .start(let firstStart) = coordinator.beginOpen(owner: "alice@example.com") else {
            XCTFail("Expected first UI action open to start")
            return
        }

        guard case .start(let secondStart) = coordinator.beginOpen(owner: "bob@example.com") else {
            XCTFail("Expected owner switch to start")
            return
        }

        XCTAssertEqual(secondStart.previousOwner, "alice@example.com")
        XCTAssertNotEqual(secondStart.attemptID, firstStart.attemptID)
        XCTAssertEqual(coordinator.currentOwner, "bob@example.com")

        XCTAssertEqual(
            coordinator.beginOpen(owner: "bob@example.com", activePhase: .connecting),
            .skipActive(owner: "bob@example.com", phase: .connecting, activeAttemptID: secondStart.attemptID)
        )
    }
}

final class AccountStreamConnectPreflightTests: XCTestCase {

    func testRestoreSkipsBeforeConfigurationDuringActivePrimaryPhases() {
        let activePhases: [AccountStreamLifecyclePhase] = [
            .connecting,
            .tlsNegotiating,
            .authenticating,
            .online
        ]

        for phase in activePhases {
            let gate = AccountStreamLifecycleGate()
            let attemptID = move(gate, to: phase)

            let decision = AccountStreamConnectPreflight.decide(
                gate: gate,
                trigger: .restore,
                forceReset: false,
                frameworkActivePhase: nil,
                streamIsDisconnected: false
            )

            XCTAssertEqual(
                decision,
                .skip(phase: phase, activeAttemptID: attemptID, reason: .gateActive),
                "Expected restore to skip before stream configuration in \(phase.rawValue)"
            )
            XCTAssertEqual(gate.snapshot().phase, phase)
            XCTAssertEqual(gate.snapshot().activeAttemptID, attemptID)
        }
    }

    func testDisconnectedFrameworkStateResetsStaleGateBeforeConfiguration() {
        let gate = AccountStreamLifecycleGate()

        guard case .start(let firstAttemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return
        }

        let decision = AccountStreamConnectPreflight.decide(
            gate: gate,
            trigger: .restore,
            forceReset: false,
            frameworkActivePhase: nil,
            streamIsDisconnected: true
        )

        guard case .start(let secondAttemptID, let stalePhase) = decision else {
            XCTFail("Expected disconnected stale gate to start a new prepared connect")
            return
        }

        XCTAssertEqual(stalePhase, .connecting)
        XCTAssertNotEqual(firstAttemptID, secondAttemptID)
        XCTAssertEqual(gate.snapshot().phase, .connecting)
        XCTAssertEqual(gate.snapshot().activeAttemptID, secondAttemptID)
    }

    func testFrameworkActivePhaseSkipsBeforeConfiguration() {
        let gate = AccountStreamLifecycleGate()

        let decision = AccountStreamConnectPreflight.decide(
            gate: gate,
            trigger: .restore,
            forceReset: false,
            frameworkActivePhase: .postAuthSetup,
            streamIsDisconnected: false
        )

        XCTAssertEqual(
            decision,
            .skip(phase: .postAuthSetup, activeAttemptID: nil, reason: .frameworkActive)
        )
        XCTAssertEqual(gate.snapshot().phase, .postAuthSetup)
        XCTAssertNil(gate.snapshot().activeAttemptID)
    }

    private func move(_ gate: AccountStreamLifecycleGate, to phase: AccountStreamLifecyclePhase) -> UInt64 {
        guard case .start(let attemptID) = gate.beginConnect(trigger: .initialLoad) else {
            XCTFail("Expected connect to start")
            return 0
        }

        switch phase {
        case .idle, .failed:
            XCTFail("Unexpected active phase \(phase)")
        case .connecting:
            break
        case .tlsNegotiating:
            gate.markTLSNegotiating()
        case .authenticating:
            gate.markTLSNegotiating()
            gate.markAuthenticating()
        case .binding:
            gate.markAuthenticating()
            gate.markBinding()
        case .postAuthSetup:
            gate.markAuthenticating()
            gate.markBinding()
            gate.markPostAuthSetup()
        case .online:
            gate.markAuthenticating()
            gate.markBinding()
            gate.markPostAuthSetup()
            gate.markOnline()
        case .disconnecting:
            gate.markDisconnecting()
        }

        return attemptID
    }
}

final class XMPPDeviceManagerRealmThreadingTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(
            inMemoryIdentifier: "XMPPDeviceManagerRealmThreadingTests-\(name)"
        )
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testUpdateMyDevicePersistsResourceFromBackgroundQueue() throws {
        let owner = "owner-\(UUID().uuidString)@example.com"
        let deviceId = "device-\(UUID().uuidString)"
        let resource = "xabber-ios-background-resource"
        let realm = try WRealm.safe()

        try realm.write {
            let account = AccountStorageItem()
            account.jid = owner
            account.deviceUuid = deviceId
            realm.add(account)

            let device = DeviceStorageItem()
            device.primary = DeviceStorageItem.genPrimary(uid: deviceId, owner: owner)
            device.owner = owner
            device.uid = deviceId
            realm.add(device)

            let resourceItem = ResourceStorageItem()
            resourceItem.primary = ResourceStorageItem.genPrimary(jid: owner, owner: owner, resource: resource)
            resourceItem.owner = owner
            resourceItem.jid = owner
            resourceItem.resource = resource
            realm.add(resourceItem)
        }

        let manager = XMPPDeviceManager(withOwner: owner)
        let callbackExpectation = expectation(description: "background update callback")

        DispatchQueue(label: "XMPPDeviceManagerRealmThreadingTests.callback").async {
            manager.updateMyDevice(resource: resource)
            callbackExpectation.fulfill()
        }

        wait(for: [callbackExpectation], timeout: 1)

        XCTAssertTrue(waitUntil {
            realm.refresh()
            let device = realm.object(
                ofType: DeviceStorageItem.self,
                forPrimaryKey: DeviceStorageItem.genPrimary(uid: deviceId, owner: owner)
            )
            let resourceItem = realm.object(
                ofType: ResourceStorageItem.self,
                forPrimaryKey: ResourceStorageItem.genPrimary(jid: owner, owner: owner, resource: resource)
            )
            return device?.resource == resource && resourceItem?.deviceId == deviceId
        })
    }

    func testPresenceReadUpdatesDeviceAndResourceInSameRealmWriteTransaction() throws {
        let owner = "owner-\(UUID().uuidString.lowercased())@example.com"
        let contact = "contact-\(UUID().uuidString.lowercased())@example.com"
        let deviceId = "remote-device-\(UUID().uuidString)"
        let resource = "xabber-ios-presence-resource"
        let realm = try WRealm.safe()

        try realm.write {
            let device = DeviceStorageItem()
            device.primary = DeviceStorageItem.genPrimary(uid: deviceId, owner: contact)
            device.owner = contact
            device.uid = deviceId
            realm.add(device)

            let resourceItem = ResourceStorageItem()
            resourceItem.primary = ResourceStorageItem.genPrimary(jid: contact, owner: owner, resource: resource)
            resourceItem.owner = owner
            resourceItem.jid = contact
            resourceItem.resource = resource
            realm.add(resourceItem)
        }

        let manager = XMPPDeviceManager(withOwner: owner)
        let presence = try XCTUnwrap(XMPPPresence(xmlString: """
        <presence from="\(contact)/\(resource)">
            <device xmlns="https://xabber.com/protocol/devices" id="\(deviceId)"/>
        </presence>
        """))

        XCTAssertTrue(manager.read(withPresence: presence, commitTransaction: true))

        let device = realm.object(
            ofType: DeviceStorageItem.self,
            forPrimaryKey: DeviceStorageItem.genPrimary(uid: deviceId, owner: contact)
        )
        let resourceItem = realm.object(
            ofType: ResourceStorageItem.self,
            forPrimaryKey: ResourceStorageItem.genPrimary(jid: contact, owner: owner, resource: resource)
        )
        XCTAssertEqual(device?.resource, resource)
        XCTAssertEqual(resourceItem?.deviceId, deviceId)
    }

    private func waitUntil(
        timeout: TimeInterval = 2,
        pollInterval: TimeInterval = 0.02,
        condition: @escaping () -> Bool
    ) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if condition() {
                return true
            }
            RunLoop.current.run(until: Date().addingTimeInterval(pollInterval))
        }
        return condition()
    }
}

final class PresenceManagerRealmWriteTests: XCTestCase {
