    }
}

final class ConnectionDiagnosticsLoggerTests: XCTestCase {

    func testLineContainsCoreConnectionFieldsInStableOrder() {
        let error = NSError(
            domain: "kCFStreamErrorDomainNetDB",
            code: -72000,
            userInfo: [NSLocalizedDescriptionKey: "DNS failed"]
        )

        let line = ConnectionDiagnosticsLogger.line(
            event: "connect start",
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 42,
            trigger: .restore,
            phase: .connecting,
            state: "connected=false,connecting=true",
            details: [
                "hostMode": "manual",
                "port": 5222
            ],
            error: error
        )

        XCTAssertTrue(line.hasPrefix("CONNECTION_DIAGNOSTICS event=\"connect start\" stream=primary jid=alice@example.com attempt=42 trigger=restore phase=connecting"))
        XCTAssertTrue(line.contains("state=\"connected=false,connecting=true\""))
        XCTAssertTrue(line.contains("errorDomain=kCFStreamErrorDomainNetDB"))
        XCTAssertTrue(line.contains("errorCode=-72000"))
        XCTAssertTrue(line.contains("errorDescription=\"DNS failed\""))
        XCTAssertTrue(line.contains("hostMode=manual"))
        XCTAssertTrue(line.contains("port=5222"))
    }

    func testLineContainsTimingAndExecutionContextFields() {
        let line = ConnectionDiagnosticsLogger.line(
            event: "tls_delegate_callback_entered",
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 7,
            phase: .tlsNegotiating,
            timing: ConnectionDiagnosticsTiming(elapsedMs: 1234, deltaMs: 56),
            executionContext: ConnectionDiagnosticsExecutionContext(
                thread: "main",
                queue: "com.xabber.account"
            )
        )

        XCTAssertTrue(line.contains("elapsedMs=1234"))
        XCTAssertTrue(line.contains("deltaMs=56"))
        XCTAssertTrue(line.contains("thread=main"))
        XCTAssertTrue(line.contains("queue=com.xabber.account"))
    }

    func testAttemptTimelineIncreasesDeltasAndResetsByAttempt() {
        let timeline = ConnectionDiagnosticsTimeline()

        let first = timeline.record(
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 1,
            now: 100
        )
        let second = timeline.record(
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 1,
            now: 101.25
        )
        let newAttempt = timeline.record(
            stream: .primary,
            jid: "alice@example.com",
            attemptID: 2,
            now: 200
        )

        XCTAssertEqual(first, ConnectionDiagnosticsTiming(elapsedMs: 0, deltaMs: nil))
        XCTAssertEqual(second, ConnectionDiagnosticsTiming(elapsedMs: 1250, deltaMs: 1250))
        XCTAssertEqual(newAttempt, ConnectionDiagnosticsTiming(elapsedMs: 0, deltaMs: nil))
    }

    func testRawXMLRedactionRemovesCredentialMaterial() {
        let xml = """
        <auth xmlns="urn:ietf:params:xml:ns:xmpp-sasl">secret-auth</auth>
        <response xmlns="urn:ietf:params:xml:ns:xmpp-sasl">secret-response</response>
        <iq type="result">
          <device>
            <secret>device-secret-value</secret>
            <validation-key>validation-key-value</validation-key>
          </device>
          <encryption-key>push-key-value</encryption-key>
          <token>token-value</token>
          <password>password-value</password>
          <item jwt="jwt-value" authorization="Bearer raw-token" />
        </iq>
        """

        let redacted = ConnectionDiagnosticsLogger.redact(xml)

        XCTAssertFalse(redacted.contains("secret-auth"))
        XCTAssertFalse(redacted.contains("secret-response"))
        XCTAssertFalse(redacted.contains("device-secret-value"))
        XCTAssertFalse(redacted.contains("validation-key-value"))
        XCTAssertFalse(redacted.contains("push-key-value"))
        XCTAssertFalse(redacted.contains("token-value"))
        XCTAssertFalse(redacted.contains("password-value"))
        XCTAssertFalse(redacted.contains("jwt-value"))
        XCTAssertFalse(redacted.contains("raw-token"))
        XCTAssertTrue(redacted.contains(ConnectionDiagnosticsLogger.redactedValue))
    }

    func testRawXMLRedactionHandlesCredentialAttributeNameVariants() {
        let xml = """
        <iq device-secret="device-secret-value"
            device_secret='device-secret-underscore-value'
            deviceSecret="device-secret-camel-value"
            xabberDeviceSecret="xabber-device-secret-value"
            validation_key="validation-key-underscore-value"
            validationKey="validation-key-camel-value"
            encryption_key="encryption-key-underscore-value"
            encryptionKey="encryption-key-camel-value"
            accessToken="access-token-camel-value"
            refreshToken="refresh-token-camel-value" />
        """

        let redacted = ConnectionDiagnosticsLogger.redact(xml)

        XCTAssertFalse(redacted.contains("device-secret-value"))
        XCTAssertFalse(redacted.contains("device-secret-underscore-value"))
        XCTAssertFalse(redacted.contains("device-secret-camel-value"))
        XCTAssertFalse(redacted.contains("xabber-device-secret-value"))
        XCTAssertFalse(redacted.contains("validation-key-underscore-value"))
        XCTAssertFalse(redacted.contains("validation-key-camel-value"))
        XCTAssertFalse(redacted.contains("encryption-key-underscore-value"))
        XCTAssertFalse(redacted.contains("encryption-key-camel-value"))
        XCTAssertFalse(redacted.contains("access-token-camel-value"))
        XCTAssertFalse(redacted.contains("refresh-token-camel-value"))
        XCTAssertTrue(redacted.contains("device-secret=\"\(ConnectionDiagnosticsLogger.redactedValue)\""))
        XCTAssertTrue(redacted.contains("device_secret='\(ConnectionDiagnosticsLogger.redactedValue)'"))
        XCTAssertTrue(redacted.contains("deviceSecret=\"\(ConnectionDiagnosticsLogger.redactedValue)\""))
    }

    func testFormatterCoversLifecycleTcpReconnectAndAccountStateEvents() {
        let lifecycle = ConnectionDiagnosticsLogger.line(
            event: "xmpp_stream_features",
            stream: .primary,
            jid: "alice@example.com",
            phase: .tlsNegotiating,
            details: [
                "startTLS": true,
                "bind": false
            ],
            rawXML: "<features><starttls /></features>",
            includeRawXML: true
        )
        let tcp = ConnectionDiagnosticsLogger.line(
            event: "tcp_socket_connected",
            stream: .background,
            jid: "alice@example.com",
            details: [
                "connectedHost": "xmpp.example.com",
                "connectedPort": 5222
            ]
        )
        let reconnect = ConnectionDiagnosticsLogger.line(
            event: "reconnect_allowed",
            stream: .primary,
            jid: "alice@example.com",
            trigger: .xmppReconnect,
            details: ["flags": "reachable"]
        )
        let accountState = ConnectionDiagnosticsLogger.line(
            event: "account_manager_mark_connecting",
            stream: .primary,
            jid: "alice@example.com",
            details: [
                "set": "connectingUsers",
                "wasPresent": false,
                "count": 1
            ]
        )
        let resilience = ConnectionDiagnosticsLogger.line(
            event: "resilience_ping_timeout",
            stream: .primary,
            jid: "alice@example.com",
            trigger: .livenessProbe,
            details: [
                "missedPings": 2,
                "limit": 2
            ]
        )

        XCTAssertTrue(lifecycle.contains("event=xmpp_stream_features"))
        XCTAssertTrue(lifecycle.contains("phase=tlsNegotiating"))
        XCTAssertTrue(lifecycle.contains("xml=\"<features><starttls /></features>\""))
        XCTAssertTrue(tcp.contains("event=tcp_socket_connected"))
        XCTAssertTrue(tcp.contains("connectedHost=xmpp.example.com"))
        XCTAssertTrue(tcp.contains("connectedPort=5222"))
        XCTAssertTrue(reconnect.contains("event=reconnect_allowed"))
        XCTAssertTrue(reconnect.contains("trigger=xmppReconnect"))
        XCTAssertTrue(accountState.contains("event=account_manager_mark_connecting"))
        XCTAssertTrue(accountState.contains("set=connectingUsers"))
        XCTAssertTrue(accountState.contains("wasPresent=false"))
        XCTAssertTrue(resilience.contains("event=resilience_ping_timeout"))
        XCTAssertTrue(resilience.contains("trigger=livenessProbe"))
        XCTAssertTrue(resilience.contains("missedPings=2"))
    }

    func testRawXMLLineUsesRedactedPayloadWhenEnabled() {
        let line = ConnectionDiagnosticsLogger.line(
            event: "stanza_receive",
            stream: .uiAction,
            jid: "alice@example.com",
            rawXML: "<message><body>Hello</body><token>token-value</token></message>",
            includeRawXML: true
        )

        XCTAssertTrue(line.contains("xml=\"<message><body>Hello</body><token>[redacted]</token></message>\""))
        XCTAssertFalse(line.contains("token-value"))
    }

    func testRawXMLLineOmitsPayloadWhenDisabled() {
        let line = ConnectionDiagnosticsLogger.line(
            event: "stanza_receive",
            stream: .primary,
            jid: "alice@example.com",
            rawXML: "<message><body>Hello</body></message>",
            includeRawXML: false
        )

        XCTAssertFalse(line.contains("xml="))
    }
}

final class SensitiveMediaAnalysisStartupSchedulerTests: XCTestCase {

    func testPrepareForLaunchDefersScanUntilAccountOnline() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.prepareForLaunch()

        XCTAssertEqual(scanCount, 0)

        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 1)
    }

    func testRepeatedOnlineEventsRunDeferredScanOnce() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.prepareForLaunch()
        scheduler.accountDidReachOnline(jid: "alice@example.com")
        scheduler.accountDidReachOnline(jid: "bob@example.com")
        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 1)
    }

    func testPrepareRunsScanWhenAccountIsAlreadyOnline() {
        var scanCount = 0
        let scheduler = SensitiveMediaAnalysisStartupScheduler {
            scanCount += 1
        }

        scheduler.accountDidReachOnline(jid: "alice@example.com")

        XCTAssertEqual(scanCount, 0)

        scheduler.prepareForLaunch()

        XCTAssertEqual(scanCount, 1)
    }
}

final class PushNotificationHardeningTests: XCTestCase {

    private func makeIQ(xml: String) throws -> XMPPIQ {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        return XMPPIQ(from: try XCTUnwrap(document.rootElement()))
    }

    func testAPNSPayloadDecoderParsesPlainJSONBody() throws {
        let body = """
        {"action":"regjid","result":"success","jid":"romeo@example.com/resource","node":"node-1","service":"push.example.com"}
        """

        let decoded = try APNSManager.decodeNodeData(from: body)

        XCTAssertEqual(decoded.action, "regjid")
        XCTAssertEqual(decoded.node, "node-1")
        XCTAssertEqual(decoded.service, "push.example.com")
    }

    func testAPNSPayloadDecoderParsesBase64JSONBody() throws {
        let json = """
        {"action":"displayed","encrypted":"payload"}
        """
        let encoded = Data(json.utf8).base64EncodedString()

        let decoded = try APNSManager.decodeNodeData(from: encoded)

        XCTAssertEqual(decoded.action, "displayed")
        XCTAssertEqual(decoded.encrypted, "payload")
    }

    func testAPNSPayloadDecoderRejectsMalformedBody() {
        XCTAssertThrowsError(try APNSManager.decodeNodeData(from: "not-json"))
    }

    func testAPNSRegistrationEligibilityUsesChannelSpecificTokens() {
        let manager = APNSManager.shared
        let previousDeviceToken = manager.deviceToken
        let previousVoIPToken = manager.voipToken

        manager.deviceToken = "device-token"
        manager.voipToken = nil
        XCTAssertTrue(manager.canSendRegistrationRequest(voip: false))
        XCTAssertFalse(manager.canSendRegistrationRequest(voip: true))

        manager.deviceToken = nil
        manager.voipToken = "voip-token"
        XCTAssertFalse(manager.canSendRegistrationRequest(voip: false))
        XCTAssertTrue(manager.canSendRegistrationRequest(voip: true))

        manager.deviceToken = previousDeviceToken
        manager.voipToken = previousVoIPToken
    }

    func testRemoteNotificationProcessingCompletesOnSuccessOnce() {
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, completion in
                completion?()
                completion?()
                return .displayed
            },
            cleanupHandler: {},
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertEqual(outcome, .push(.displayed))
        XCTAssertEqual(completionResults, [.newData])
    }

    func testRemoteNotificationProcessingCompletesOnInvalidPayload() {
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, _ in throw APNSManager.APNSError.invalidPayload },
            cleanupHandler: {},
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertEqual(outcome, .noData)
        XCTAssertEqual(completionResults, [.noData])
    }

    func testRemoteNotificationProcessingCleansUpUnknownUserAndCompletes() {
        var didCleanup = false
        var completionResults: [UIBackgroundFetchResult] = []

        let outcome = AppDelegate.processRemoteNotification(
            userInfo: [:],
            voipHandler: { _ in false },
            apnsHandler: { _, _ in throw APNSManager.APNSError.userNotExist },
            cleanupHandler: { didCleanup = true },
            fetchCompletionHandler: { completionResults.append($0) }
        )

        XCTAssertTrue(didCleanup)
        XCTAssertEqual(outcome, .noData)
        XCTAssertEqual(completionResults, [.noData])
    }

    func testPushEnableStaysPendingUntilIQResultArrives() {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        XCTAssertEqual(manager.enableState, .pending(queryId: queryId))
        XCTAssertTrue(callbackResults.isEmpty)

        CredentialsManager.shared.removePushCredentials(for: node)
    }

    func testPushEnableBecomesEnabledAfterSuccessfulIQResult() throws {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <x xmlns='jabber:x:data'>
            <field var='url'><value>https://push.example.com</value></field>
            <field var='jwt'><value>jwt-token</value></field>
          </x>
        </iq>
        """)

        XCTAssertTrue(manager.read(withIQ: iq))
        XCTAssertEqual(manager.enableState, .enabled)
        XCTAssertEqual(callbackResults, [true])
        XCTAssertFalse(manager.queryIds.contains(queryId))

        let credentials = try CredentialsManager.shared.getPushCredentials(for: node)
        XCTAssertEqual(credentials.service, "https://push.example.com")
        XCTAssertEqual(credentials.jwt, "jwt-token")

        CredentialsManager.shared.removePushCredentials(for: node)
    }

    func testPushEnableResetsToDisabledAfterIncompleteIQResult() throws {
        let owner = "romeo@example.com"
        let node = "push-node-\(UUID().uuidString)"
        let manager = PushNotificationsManager(withOwner: owner)
        manager.node = node
        manager.service = "pubsub.example.com"

        let stream = XMPPStream()
        stream.myJID = XMPPJID(string: "\(owner)/ios")

        var callbackResults: [Bool] = []
        manager.enable(xmppStream: stream) { callbackResults.append($0) }

        guard let queryId = manager.queryIds.first else {
            XCTFail("Expected pending query id")
            return
        }

        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <x xmlns='jabber:x:data'>
            <field var='url'><value>https://push.example.com</value></field>
          </x>
        </iq>
        """)

        XCTAssertTrue(manager.read(withIQ: iq))
        XCTAssertEqual(manager.enableState, .disabled)
        XCTAssertEqual(callbackResults, [false])
        XCTAssertFalse(manager.queryIds.contains(queryId))

        CredentialsManager.shared.removePushCredentials(for: node)
    }
}

final class NotificationsFeatureTests: XCTestCase {

    private let owner = "igor.boldin@xmppdev01.xabber.com"
    private let notificationsNode = "notifications.xmppdev01.xabber.com"
    private let groupchatJid = "trio@example.com"
    private let groupchatAuthorJid = "romeo@xmppdev01.xabber.com"
    private let currentMemberId = "me-1"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "NotificationsFeatureTests-\(name)")
        AccountManager.shared.users.removeAll { $0.jid == owner }
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    override func tearDown() {
        AccountManager.shared.users.removeAll { $0.jid == owner }
        super.tearDown()
    }

    private func makeMessage(xml: String) throws -> XMPPMessage {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "NotificationsFeatureTests", code: 1)
        }
        return XMPPMessage(from: root)
    }

    private func makeIQ(xml: String) throws -> XMPPIQ {
        let document = try DDXMLDocument(xmlString: xml, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "NotificationsFeatureTests", code: 2)
        }
        return XMPPIQ(from: root)
    }

    private func makeAccount() -> Account {
        AccountManager.shared.users.removeAll { $0.jid == owner }
        let account = Account(jid: owner, queue: .main)
        account.sendReadiness.markStreamManagementEnabled()
        AccountManager.shared.users.append(account)
        return account
    }

    private func upsertNotificationManagerStorage(
        node: String,
        archiveSyncCompleted: Bool = false,
        lastSyncedNotificationId: String? = nil,
        lastItemId: String? = nil,
        unread: Int = 0,
        unreadAfterId: String? = nil
    ) throws {
        let realm = try WRealm.safe()
        let storage = XMPPNotificationsManagerStorageItem()
        storage.owner = owner
        storage.primary = XMPPNotificationsManagerStorageItem.genPrimary(owner: owner)
        storage.node = node
        storage.archiveSyncCompleted = archiveSyncCompleted
        storage.lastSyncedNotificationId = lastSyncedNotificationId
        storage.lastItemId = lastItemId
        storage.unread = unread
        storage.unreadAfterId = unreadAfterId

        try realm.write {
            realm.add(storage, update: .modified)
        }
    }

    @discardableResult
    private func insertNotification(
        jid: String = "security@xmppdev01.xabber.com",
        uniqueId: String,
        stanzaId: String?,
        date: String
    ) throws -> NotificationStorageItem {
        let realm = try WRealm.safe()
        let notification = NotificationStorageItem()
        notification.primary = NotificationStorageItem.genPrimary(owner: owner, jid: jid, uniqueId: uniqueId)
        notification.owner = owner
        notification.jid = jid
        notification.uniqueId = uniqueId
        notification.messageId = uniqueId
        notification.stanzaId = stanzaId ?? ""
        notification.category = .info
        notification.shouldShow = true
        notification.date = ISO8601DateFormatter().date(from: date)!

        try realm.write {
            realm.add(notification, update: .modified)
        }

        return notification
    }

    private func queuedNotificationRequest(on account: Account) -> MessageArchiveManager.CallbackQueueItem? {
        account.mam.callbacksQueue.first(where: { $0.task.conversationType == .notifications })
    }

    private func waitForQueuedNotificationRequest(
        on account: Account,
        timeout: TimeInterval = 1.0,
        file: StaticString = #filePath,
        line: UInt = #line
    ) -> MessageArchiveManager.CallbackQueueItem {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if let queued = queuedNotificationRequest(on: account) {
                return queued
            }
            RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.01))
        }

        XCTFail("Expected queued notification archive request", file: file, line: line)
        return account.mam.callbacksQueue.first!
    }

    private func sendArchiveFin(
        on account: Account,
        queryId: String,
        complete: Bool,
        count: Int,
        first: String,
        last: String
    ) throws {
        let iq = try makeIQ(xml: """
        <iq type='result' id='\(queryId)'>
          <fin xmlns='urn:xmpp:mam:2' complete='\(complete ? "true" : "false")' queryid='\(queryId)'>
            <set xmlns='http://jabber.org/protocol/rsm'>
              <count>\(count)</count>
              <first>\(first)</first>
              <last>\(last)</last>
            </set>
          </fin>
        </iq>
        """)

        XCTAssertTrue(account.mam.read(account.xmppStream, withIQ: iq))
    }

    private func managerStorage() throws -> XMPPNotificationsManagerStorageItem? {
        try WRealm.safe().object(ofType: XMPPNotificationsManagerStorageItem.self, forPrimaryKey: XMPPNotificationsManagerStorageItem.genPrimary(owner: owner))
    }

    private func makeArchivedInfoNotificationMessage(
