final class MessageReceiverBatchingTests: XCTestCase {

    private let owner = "igor.boldin@xmppdev01.xabber.com"

    override func setUp() {
        super.setUp()
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "MessageReceiverBatchingTests-\(name)")
        let realm = try! WRealm.safe()
        try! realm.write {
            realm.deleteAll()
        }
    }

    private func makeMessage(id: String) throws -> XMPPMessage {
        let document = try DDXMLDocument(xmlString: """
        <message type='chat' id='\(id)' from='alexey.boldin@xmppdev01.xabber.com' to='\(owner)'>
          <body>Hello</body>
        </message>
        """, options: 0)
        guard let root = document.rootElement() else {
            throw NSError(domain: "MessageReceiverBatchingTests", code: 1)
        }
        return XMPPMessage(from: root)
    }

    func testEnqueueCollectionBatchesIntoMessagesQueue() throws {
        let manager = MessageManager(withOwner: owner, activeStream: false)
        manager.unsubscribeReceiver()
        manager.clearQueue()

        let first = MessageManager.MessageQueueItem(
            try makeMessage(id: "m1"),
            messageId: "m1",
            archivedFrom: "alexey.boldin@xmppdev01.xabber.com",
            isRead: false,
            date: Date(timeIntervalSince1970: 1),
            state: .deliver,
            queryId: "history-1"
        )
        let second = MessageManager.MessageQueueItem(
            try makeMessage(id: "m2"),
            messageId: "m2",
            archivedFrom: "alexey.boldin@xmppdev01.xabber.com",
            isRead: false,
            date: Date(timeIntervalSince1970: 2),
            state: .deliver,
            queryId: "history-1"
        )

        manager.enqueue(collection: [first, second])

        XCTAssertEqual(manager.messagesQueue.value.count, 2)
    }

    func testDuplicateMessageMergesArchiveProducingQueryMetadata() throws {
        let realm = try WRealm.safe()
        let existing = MessageStorageItem()
        existing.primary = MessageStorageItem.genPrimary(messageId: "m1", owner: owner)
        existing.owner = owner
        existing.opponent = "alexey.boldin@xmppdev01.xabber.com"
        existing.messageId = "m1"
        existing.queryIds = "existing-history"

        try realm.write {
            realm.add(existing, update: .modified)
        }

        let incoming = MessageStorageItem()
        incoming.primary = existing.primary
        incoming.owner = owner
        incoming.opponent = existing.opponent
        incoming.messageId = "m1"
        incoming.queryIds = "MAM next history: archive-page"
        incoming.shouldPersistArchiveQueryId = true

        try realm.write {
            _ = incoming.applyMessagePersistence(in: realm)
        }

        XCTAssertEqual(existing.queryIds, "existing-history,MAM next history: archive-page")
    }

    func testDuplicateMessageIgnoresNonArchiveQueryMetadata() throws {
        let realm = try WRealm.safe()
        let existing = MessageStorageItem()
        existing.primary = MessageStorageItem.genPrimary(messageId: "m1", owner: owner)
        existing.owner = owner
        existing.opponent = "alexey.boldin@xmppdev01.xabber.com"
        existing.messageId = "m1"
        existing.queryIds = "existing-history"

        try realm.write {
            realm.add(existing, update: .modified)
        }

        let incoming = MessageStorageItem()
        incoming.primary = existing.primary
        incoming.owner = owner
        incoming.opponent = existing.opponent
        incoming.messageId = "m1"
        incoming.queryIds = "MAM search: result"
        incoming.shouldPersistArchiveQueryId = false

        try realm.write {
            _ = incoming.applyMessagePersistence(in: realm)
        }

        XCTAssertEqual(existing.queryIds, "existing-history")
    }
}

final class ChatDatasetPerformanceHelpersTests: XCTestCase {

    func testMapReferenceAttachmentsPartitionsReferencesInOnePass() {
        let image = MessageReferenceStorageItem()
        image.primary = "image"
        image.mimeType = "image/jpeg"
        image.kind = .media
        image.isSensitive = true

        let video = MessageReferenceStorageItem()
        video.primary = "video"
        video.mimeType = "video/mp4"
        video.kind = .media
        video.isSensitive = true

        let audio = MessageReferenceStorageItem()
        audio.primary = "audio"
        audio.kind = .voice
        audio.kind_ = "voice"

        let file = MessageReferenceStorageItem()
        file.primary = "file"
        file.mimeType = "application/pdf"
        file.kind = .media
        file.name = "spec.pdf"

        let groupchatFile = MessageReferenceStorageItem()
        groupchatFile.primary = "group-file"
        groupchatFile.mimeType = "application/pdf"
        groupchatFile.kind = .media
        groupchatFile.kind_ = "groupchat"

        let result = ChatViewController.mapReferenceAttachments([image, video, audio, file, groupchatFile])

        XCTAssertEqual(result.images.map(\.primary), ["image"])
        XCTAssertEqual(result.videos.map(\.primary), ["video"])
        XCTAssertEqual(result.audio.map(\.primary), ["audio"])
        XCTAssertEqual(result.files.map(\.primary), ["file"])
        XCTAssertTrue(result.images.first?.isSensitive == true)
        XCTAssertTrue(result.videos.first?.isSensitive == true)
    }

    func testMapReferenceAttachmentsUsesLocalImageFileBeforeUploadCompletes() throws {
        let localURL = try XCTUnwrap(URL(string: "file:///tmp/uploading-local-image.jpg"))
        let image = MessageReferenceStorageItem()
        image.primary = "uploading-image"
        image.mimeType = "image/jpeg"
        image.kind = .media
        image.metadata = ["media-type": "image/jpeg"]
        image.localFileUrl = localURL

        let result = ChatViewController.mapReferenceAttachments([image])

        XCTAssertEqual(result.images.map(\.primary), ["uploading-image"])
        XCTAssertEqual(result.images.first?.url, localURL)
    }

    func testMapReferenceAttachmentsPrefersRemoteImageUrlAfterUploadCompletes() throws {
        let localURL = try XCTUnwrap(URL(string: "file:///tmp/uploading-local-image.jpg"))
        let remoteURL = try XCTUnwrap(URL(string: "https://files.example.com/uploaded-image.jpg"))
        let image = MessageReferenceStorageItem()
        image.primary = "uploaded-image"
        image.mimeType = "image/jpeg"
        image.kind = .media
        image.metadata = ["media-type": "image/jpeg"]
        image.localFileUrl = localURL
        image.downloadUrl = remoteURL

        let result = ChatViewController.mapReferenceAttachments([image])

        XCTAssertEqual(result.images.map(\.primary), ["uploaded-image"])
        XCTAssertEqual(result.images.first?.url, remoteURL)
    }

    func testMapReferenceAttachmentsDoesNotUseAssetUriAsUploadingImagePreview() throws {
        let assetURL = try XCTUnwrap(URL(string: "asset://photo-library-local-id"))
        let image = MessageReferenceStorageItem()
        image.primary = "asset-image"
        image.mimeType = "image/jpeg"
        image.kind = .media
        image.metadata = [
            "media-type": "image/jpeg",
