final class ChatMessageUpdatePolicyTests: XCTestCase {
    private func makeDatasource(
        primary: String = "message-1",
        text: String = "Hello",
        state: MessageStorageItem.MessageSendingState = .sending,
        indicator: IndicatorType = .sending,
        editDate: Date? = nil,
        images: [ImageAttachment] = [],
        videos: [VideoAttachment] = [],
        files: [FileAttachment] = [],
        audios: [AudioAttachment] = [],
        forwards: [MessageAttachment] = [],
        archivedId: String? = "archived-1",
        sentDate: Date = Date(timeIntervalSince1970: 100),
        timeMarkerText: NSAttributedString = NSAttributedString(string: "12:00")
    ) -> ChatViewController.Datasource {
        ChatViewController.Datasource(
            primary: primary,
            jid: "romeo@example.com",
            owner: "owner@example.com",
            outgoing: true,
            sender: Sender(id: "owner@example.com", displayName: "Owner"),
            messageId: "\(primary)-message-id",
            sentDate: sentDate,
            editDate: editDate,
            kind: .attributedText(NSAttributedString(string: text)),
            withAuthor: false,
            withAvatar: false,
            error: state == .error,
            errorType: "",
            canPinMessage: false,
            canEditMessage: true,
            canDeleteMessage: true,
            forwards: forwards,
            isOutgoing: true,
            isEdited: editDate != nil,
            groupchatAuthorRole: "",
            groupchatAuthorId: "",
            groupchatAuthorNickname: "",
            groupchatAuthorBadge: "",
            isHasAttachedMessages: false,
            isDownloaded: true,
            state: state,
            searchString: nil,
            errorMetadata: nil,
            burnDate: -1,
            afterburnInterval: -1,
            archivedId: archivedId,
            queryIds: nil,
            isRead: true,
            selectedSearchResultId: nil,
            isHadHistoryGap: false,
            tailed: false,
            isFakeMessage: false,
            images: images,
            videos: videos,
            files: files,
            audios: audios,
            timeMarkerText: timeMarkerText,
            indicator: indicator,
            avatarUrl: nil,
            attributedAuthor: nil
        )
    }

    private func diff(
        old oldItems: [ChatViewController.Datasource],
        new newItems: [ChatViewController.Datasource],
        oldSize: CGSize = CGSize(width: 320, height: 44),
        newSize: CGSize = CGSize(width: 320, height: 44)
    ) -> ChatDatasourceCoordinator.DiffResult {
        ChatDatasourceCoordinator.diff(
            old: ChatDatasourceCoordinator.makeSnapshot(items: oldItems),
            new: ChatDatasourceCoordinator.makeSnapshot(items: newItems),
            oldSizeProvider: { _ in oldSize },
            newSizeProvider: { _ in newSize }
        )
    }

    func testDeliveryStatusChangeWithUnchangedSizeChoosesContentOnlyUpdate() {
        let old = makeDatasource(state: .sending, indicator: .sending)
        let new = makeDatasource(state: .read, indicator: .read)

        let result = diff(old: [old], new: [new])

        XCTAssertEqual(result.contentOnlyUpdates.map(\.primary), ["message-1"])
        XCTAssertTrue(result.reloads.isEmpty)
        XCTAssertTrue(result.inserts.isEmpty)
        XCTAssertTrue(result.deletes.isEmpty)
    }

    func testNonNoneIndicatorSwapStaysContentOnlyButNoneIndicatorTransitionAffectsLayout() {
        let sending = makeDatasource(state: .sending, indicator: .sending)
        let read = makeDatasource(state: .read, indicator: .read)
        let noIndicator = makeDatasource(state: .none, indicator: .none)

        let nonNoneSwap = diff(old: [sending], new: [read])
        let noneTransition = diff(old: [noIndicator], new: [sending])

        XCTAssertEqual(nonNoneSwap.contentOnlyUpdates.map(\.primary), ["message-1"])
        XCTAssertTrue(nonNoneSwap.reloads.isEmpty)
        XCTAssertTrue(noneTransition.contentOnlyUpdates.isEmpty)
        XCTAssertEqual(noneTransition.reloads, [IndexPath(item: 0, section: 0)])
    }

    func testEditedTextWithUnchangedMeasuredSizeChoosesContentOnlyUpdate() {
        let old = makeDatasource(text: "Hello world")
        let new = makeDatasource(
            text: "Hallo world",
            editDate: Date(timeIntervalSince1970: 200),
            timeMarkerText: NSAttributedString(string: "12:00 edited")
        )

        let result = diff(old: [old], new: [new])

        XCTAssertEqual(result.contentOnlyUpdates.map(\.primary), ["message-1"])
        XCTAssertTrue(result.reloads.isEmpty)
    }

    func testEditedTextWithChangedMeasuredSizeInvalidatesLayout() {
        let old = makeDatasource(text: "Short")
        let new = makeDatasource(text: "A much longer edited message")

        let result = diff(
            old: [old],
            new: [new],
            oldSize: CGSize(width: 320, height: 44),
            newSize: CGSize(width: 320, height: 88)
        )

        XCTAssertTrue(result.contentOnlyUpdates.isEmpty)
        XCTAssertEqual(result.reloads, [IndexPath(item: 0, section: 0)])
    }

    func testAttachmentIdentityOrCountChangeInvalidatesLayout() {
        let firstAudio = AudioAttachment(
            primary: "audio-1",
            url: URL(string: "file:///audio-1.ogg"),
            size: 1,
            name: "voice",
            duration: 1,
            downloaded: true,
            pcm: [0.2]
        )
        let secondAudio = AudioAttachment(
            primary: "audio-2",
            url: URL(string: "file:///audio-2.ogg"),
            size: 1,
            name: "voice",
            duration: 1,
            downloaded: true,
            pcm: [0.3]
        )
        let old = makeDatasource(audios: [firstAudio])
        let new = makeDatasource(audios: [firstAudio, secondAudio])

        let result = diff(old: [old], new: [new])

        XCTAssertTrue(result.contentOnlyUpdates.isEmpty)
        XCTAssertEqual(result.reloads, [IndexPath(item: 0, section: 0)])
    }

    func testInsertDeleteMoveStayStructuralWhenKeysAreUnique() {
        let first = makeDatasource(primary: "first", archivedId: "a1")
        let second = makeDatasource(primary: "second", archivedId: "a2")
        let third = makeDatasource(primary: "third", archivedId: "a3")

        let result = diff(old: [first, third], new: [third, first, second])

        XCTAssertFalse(result.inserts.isEmpty)
        XCTAssertFalse(result.moves.isEmpty)
        XCTAssertTrue(result.contentOnlyUpdates.isEmpty)
        XCTAssertFalse(
            ChatMessageUpdatePolicy.shouldUseReloadFallback(
                old: ChatDatasourceCoordinator.makeSnapshot(items: [first, third]),
                new: ChatDatasourceCoordinator.makeSnapshot(items: [third, first, second])
            )
        )
    }

    func testDuplicateKeysChooseReloadFallback() {
        let first = makeDatasource(primary: "duplicate", archivedId: "a1")
        let second = makeDatasource(primary: "duplicate", archivedId: "a2")
        let snapshot = ChatDatasourceCoordinator.makeSnapshot(items: [first, second])

        XCTAssertTrue(
            ChatMessageUpdatePolicy.shouldUseReloadFallback(old: snapshot, new: snapshot)
        )
    }
}

final class ChatOutgoingAutoScrollPolicyTests: XCTestCase {
    private func makeDatasource(
        primary: String,
        outgoing: Bool = true,
        isFakeMessage: Bool = false
    ) -> ChatViewController.Datasource {
        ChatViewController.Datasource(
            primary: primary,
            jid: "romeo@example.com",
            owner: "owner@example.com",
            outgoing: outgoing,
            sender: Sender(
                id: outgoing ? "owner@example.com" : "romeo@example.com",
                displayName: outgoing ? "Owner" : "Romeo"
            ),
            messageId: "\(primary)-message-id",
            sentDate: Date(timeIntervalSince1970: 100),
            editDate: nil,
            kind: .attributedText(NSAttributedString(string: primary)),
            withAuthor: false,
            withAvatar: false,
            error: false,
            errorType: "",
            canPinMessage: false,
            canEditMessage: outgoing,
            canDeleteMessage: true,
            forwards: [],
            isOutgoing: outgoing,
            isEdited: false,
            groupchatAuthorRole: "",
            groupchatAuthorId: "",
            groupchatAuthorNickname: "",
            groupchatAuthorBadge: "",
            isHasAttachedMessages: false,
            isDownloaded: true,
            state: .read,
            searchString: nil,
            errorMetadata: nil,
            burnDate: -1,
            afterburnInterval: -1,
            archivedId: "\(primary)-archived",
            queryIds: nil,
            isRead: true,
            selectedSearchResultId: nil,
            isHadHistoryGap: false,
            tailed: false,
            isFakeMessage: isFakeMessage,
            images: [],
            videos: [],
            files: [],
            audios: [],
            timeMarkerText: NSAttributedString(string: ""),
            indicator: .none,
            avatarUrl: nil,
            attributedAuthor: nil
        )
    }

    func testPendingOutgoingNewestNotVisibleScrollsToNewest() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [
                makeDatasource(primary: "old"),
                makeDatasource(primary: "new")
            ],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .scroll(IndexPath(item: 0, section: 1)))
        XCTAssertTrue(decision.consumesPendingRequest)
    }

    func testPendingOutgoingNewestAlreadyVisibleStillScrollsToNewest() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [
                makeDatasource(primary: "old"),
                makeDatasource(primary: "new")
            ],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .scroll(IndexPath(item: 0, section: 1)))
        XCTAssertTrue(decision.consumesPendingRequest)
    }

    func testNoPendingRequestDoesNotCreateOutgoingScrollAction() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: nil,
            items: [makeDatasource(primary: "new")],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .notHandled)
        XCTAssertFalse(decision.consumesPendingRequest)
    }

    func testNewestIncomingClearsPendingRequestAndLeavesDefaultBehaviorAvailable() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [
                makeDatasource(primary: "old"),
                makeDatasource(primary: "incoming", outgoing: false)
            ],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .useDefaultAndClear)
        XCTAssertTrue(decision.consumesPendingRequest)
    }

    func testFakeNewestRowIsIgnoredForOutgoingAutoScroll() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [
                makeDatasource(primary: "old"),
                makeDatasource(primary: "old date", isFakeMessage: true)
            ],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .notHandled)
        XCTAssertFalse(decision.consumesPendingRequest)
    }

    func testUnchangedNewestEdgeDoesNotConsumePendingRequest() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [makeDatasource(primary: "old")],
            isAnchorNavigationActive: false
        )

        XCTAssertEqual(decision, .notHandled)
        XCTAssertFalse(decision.consumesPendingRequest)
    }

    func testActiveAnchorNavigationBlocksOutgoingAutoScroll() {
        let decision = ChatOutgoingAutoScrollPolicy.decision(
            request: ChatOutgoingAutoScrollRequest(previousNewestPrimary: "old"),
            items: [
                makeDatasource(primary: "old"),
                makeDatasource(primary: "new")
            ],
            isAnchorNavigationActive: true
        )

        XCTAssertEqual(decision, .handledNoScroll)
        XCTAssertTrue(decision.consumesPendingRequest)
    }
}

final class InlineAudiosGridViewContentUpdateTests: XCTestCase {
    func testSamePrimaryAudioUpdateReusesExistingAudioView() {
        let grid = InlineAudiosGridView(frame: CGRect(x: 0, y: 0, width: 320, height: 44))
        let original = AudioAttachment(
            primary: "audio-1",
            url: URL(string: "file:///original.ogg"),
            size: 1,
            name: "voice",
            duration: 1,
            downloaded: true,
            pcm: [0.2]
        )
        let updated = AudioAttachment(
            primary: "audio-1",
            url: URL(string: "file:///updated.ogg"),
            size: 1,
            name: "voice",
            duration: 2,
            downloaded: true,
            pcm: [0.5, 0.6]
        )

        grid.configure([original], palette: .blue)
        let initialView = grid.views.first

        grid.updateContent([updated], palette: .blue)

        XCTAssertTrue(grid.views.first === initialView)
        XCTAssertEqual(grid.views.first?.url, updated.url)
        XCTAssertEqual(grid.views.first?.duration, updated.duration)
        XCTAssertEqual(grid.views.first?.primary, updated.primary)
    }
}

private struct SensitiveMediaAnalysisTestError: Error, LocalizedError {
    var errorDescription: String? {
        return "analysis failed"
    }
}

private final class FakeSensitiveMediaAnalyzer: SensitiveMediaAnalyzing {
    var analysisPolicy: SensitiveMediaAnalysisPolicy
    var imageFileResult: Result<Bool, Error>
    var imageResult: Result<Bool, Error>
    var videoFileResult: Result<Bool, Error>
    var delayNanoseconds: UInt64

    private let lock = NSLock()
    private var _imageFileCallCount = 0
    private var _imageCallCount = 0
    private var _videoFileCallCount = 0

    var imageFileCallCount: Int {
        locked { _imageFileCallCount }
    }

    var imageCallCount: Int {
        locked { _imageCallCount }
    }

    var videoFileCallCount: Int {
        locked { _videoFileCallCount }
    }

    init(
        analysisPolicy: SensitiveMediaAnalysisPolicy = .enabled,
        imageFileResult: Result<Bool, Error> = .success(false),
        imageResult: Result<Bool, Error> = .success(false),
        videoFileResult: Result<Bool, Error> = .success(false),
        delayNanoseconds: UInt64 = 0
    ) {
        self.analysisPolicy = analysisPolicy
        self.imageFileResult = imageFileResult
        self.imageResult = imageResult
        self.videoFileResult = videoFileResult
        self.delayNanoseconds = delayNanoseconds
    }

    func analyzeImageFile(at url: URL) async throws -> Bool {
        incrementImageFileCalls()
        try await delayIfNeeded()
        return try imageFileResult.get()
    }

    func analyzeImage(_ cgImage: CGImage) async throws -> Bool {
        incrementImageCalls()
        try await delayIfNeeded()
        return try imageResult.get()
    }

    func analyzeVideoFile(at url: URL) async throws -> Bool {
        incrementVideoFileCalls()
        try await delayIfNeeded()
        return try videoFileResult.get()
    }

    private func delayIfNeeded() async throws {
        if delayNanoseconds > 0 {
            try await Task.sleep(nanoseconds: delayNanoseconds)
        }
    }

    private func incrementImageFileCalls() {
        locked { _imageFileCallCount += 1 }
    }

    private func incrementImageCalls() {
        locked { _imageCallCount += 1 }
    }

    private func incrementVideoFileCalls() {
        locked { _videoFileCallCount += 1 }
    }

    private func locked<T>(_ body: () -> T) -> T {
        lock.lock()
        defer { lock.unlock() }
        return body()
    }
}

private final class FakeSensitiveMediaFileProvider: SensitiveMediaFileProviding {
    var imageResult: Result<CGImage, Error>
    var videoResult: Result<SensitiveMediaAnalysisLocalFile, Error>

    init(
        imageResult: Result<CGImage, Error> = .success(FakeSensitiveMediaFileProvider.makeCGImage()),
        videoResult: Result<SensitiveMediaAnalysisLocalFile, Error> = .failure(SensitiveMediaAnalysisTestError())
    ) {
        self.imageResult = imageResult
        self.videoResult = videoResult
    }

    func downloadImageCGImage(from url: URL) async throws -> CGImage {
        return try imageResult.get()
    }

    func localVideoFile(from url: URL) async throws -> SensitiveMediaAnalysisLocalFile {
        return try videoResult.get()
    }

    private static func makeCGImage() -> CGImage {
        let colorSpace = CGColorSpaceCreateDeviceRGB()
        let data = Data([255, 0, 0, 255]) as CFData
        let provider = CGDataProvider(data: data)!
        return CGImage(
            width: 1,
            height: 1,
            bitsPerComponent: 8,
            bitsPerPixel: 32,
            bytesPerRow: 4,
            space: colorSpace,
            bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue),
            provider: provider,
            decode: nil,
            shouldInterpolate: false,
            intent: .defaultIntent
        )!
    }
}

final class MessageReferenceVideoPreviewPreparationTests: XCTestCase {
    private var previousScheduler: MessageReferenceVideoPreviewScheduling!

    override func setUp() {
        super.setUp()
        previousScheduler = MessageReferenceStorageItem.videoPreviewScheduler
    }

    override func tearDown() {
        MessageReferenceStorageItem.videoPreviewScheduler = previousScheduler
        previousScheduler = nil
        super.tearDown()
    }

    func testPrepareSchedulesVideoPreviewWithoutRunningPreviewInline() {
        let scheduler = CapturingMessageReferenceVideoPreviewScheduler()
        MessageReferenceStorageItem.videoPreviewScheduler = scheduler
        let reference = MessageReferenceStorageItem()
        reference.primary = "video-reference-1"
        reference.kind = .media
        reference.mimeType = "video"
        reference.isDownloaded = false
        reference.url = "https://example.com/video.mp4"
        reference.metadata = ["media-type": "video"]

        let started = Date()
        reference.prepare()

        XCTAssertEqual(scheduler.scheduledPrimaryKeys, ["video-reference-1"])
        XCTAssertLessThan(Date().timeIntervalSince(started), 0.05)
    }

    func testPrepareDoesNotSchedulePreviewForNonVideoReference() {
        let scheduler = CapturingMessageReferenceVideoPreviewScheduler()
        MessageReferenceStorageItem.videoPreviewScheduler = scheduler
        let reference = MessageReferenceStorageItem()
        reference.primary = "image-reference-1"
        reference.kind = .media
        reference.mimeType = "image/jpeg"
        reference.isDownloaded = false
        reference.url = "https://example.com/image.jpg"
        reference.metadata = ["media-type": "image"]

        reference.prepare()

        XCTAssertTrue(scheduler.scheduledPrimaryKeys.isEmpty)
    }
}

private final class CapturingMessageReferenceVideoPreviewScheduler: MessageReferenceVideoPreviewScheduling {
    var scheduledPrimaryKeys: [String] = []

    func schedule(referencePrimary: String) {
        scheduledPrimaryKeys.append(referencePrimary)
    }
}

final class SensitiveMediaAnalysisServiceTests: XCTestCase {
    private var previousRealmConfiguration: Realm.Configuration!
    private var tempURLs: [URL] = []

    override func setUp() {
        super.setUp()
        previousRealmConfiguration = Realm.Configuration.defaultConfiguration
        Realm.Configuration.defaultConfiguration = Realm.Configuration(inMemoryIdentifier: "SensitiveMediaAnalysisServiceTests-\(name)")
    }

    override func tearDown() {
        tempURLs.forEach { try? FileManager.default.removeItem(at: $0) }
        tempURLs.removeAll()
        Realm.Configuration.defaultConfiguration = previousRealmConfiguration
        previousRealmConfiguration = nil
        super.tearDown()
    }

    func testMIMEDetectionSupportsImagesAndVideos() {
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .media, mimeType: "image/jpeg", mediaType: nil), .image)
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .media, mimeType: "image/png", mediaType: nil), .image)
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .media, mimeType: "video/mp4", mediaType: nil), .video)
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .media, mimeType: "video/quicktime", mediaType: nil), .video)
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .media, mimeType: "application/pdf", mediaType: nil), .unsupported)
        XCTAssertEqual(SensitiveMediaAnalysisService.sensitiveAnalyzableMediaType(kind: .voice, mimeType: "audio/ogg", mediaType: nil), .unsupported)
    }

    func testImageSensitiveResultTruePersistsCheckedStateAndInvalidatesMessage() async throws {
        let referencePrimary = try insertMediaReference(primary: "image-true", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg")
        let analyzer = FakeSensitiveMediaAnalyzer(imageFileResult: .success(true))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider(), dateProvider: { Date(timeIntervalSince1970: 100) })

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        let attachment = try XCTUnwrap(realm.object(ofType: MessageMediaAttachmentStorageItem.self, forPrimaryKey: "attachment-\(referencePrimary)"))
        let message = try XCTUnwrap(realm.object(ofType: MessageStorageItem.self, forPrimaryKey: "message-\(referencePrimary)"))
        XCTAssertTrue(reference.isSensitive)
        XCTAssertTrue(reference.isSensitiveChecked)
        XCTAssertEqual(reference.sensitivityCheckedAt, Date(timeIntervalSince1970: 100))
        XCTAssertEqual(reference.sensitivitySource, SensitiveMediaAnalysisService.sourceAppleSCA)
        XCTAssertNil(reference.sensitivityAnalysisFailedAt)
        XCTAssertTrue(attachment.isSensitive)
        XCTAssertTrue(attachment.isSensitiveChecked)
        XCTAssertTrue(message.queryIds?.contains("sensitivity") == true)
        XCTAssertEqual(analyzer.imageFileCallCount, 1)
    }

    func testImageSensitiveResultFalseStillPersistsCheckedState() async throws {
        let referencePrimary = try insertMediaReference(primary: "image-false", mimeType: "image/png", mediaType: "image", fileExtension: "png")
        let analyzer = FakeSensitiveMediaAnalyzer(imageFileResult: .success(false))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider())

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        XCTAssertFalse(reference.isSensitive)
        XCTAssertTrue(reference.isSensitiveChecked)
        XCTAssertEqual(reference.sensitivitySource, SensitiveMediaAnalysisService.sourceAppleSCA)
    }

    func testVideoSensitiveResultTruePersistsCheckedState() async throws {
        let referencePrimary = try insertMediaReference(primary: "video-true", mimeType: "video/mp4", mediaType: "video", fileExtension: "mp4")
        let analyzer = FakeSensitiveMediaAnalyzer(videoFileResult: .success(true))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider())

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        XCTAssertTrue(reference.isSensitive)
        XCTAssertTrue(reference.isSensitiveChecked)
        XCTAssertEqual(analyzer.videoFileCallCount, 1)
    }

    func testVideoSensitiveResultFalseStillPersistsCheckedState() async throws {
        let referencePrimary = try insertMediaReference(primary: "video-false", mimeType: "video/quicktime", mediaType: "video", fileExtension: "mov")
        let analyzer = FakeSensitiveMediaAnalyzer(videoFileResult: .success(false))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider())

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        XCTAssertFalse(reference.isSensitive)
        XCTAssertTrue(reference.isSensitiveChecked)
    }

    func testDisabledPolicyDoesNotClearExistingSensitiveFlagOrMarkChecked() async throws {
        let referencePrimary = try insertMediaReference(primary: "disabled", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg", isSensitive: true)
        let analyzer = FakeSensitiveMediaAnalyzer(analysisPolicy: .disabled, imageFileResult: .success(false))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider())

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        XCTAssertTrue(reference.isSensitive)
        XCTAssertFalse(reference.isSensitiveChecked)
        XCTAssertNil(reference.sensitivityCheckedAt)
        XCTAssertNil(reference.sensitivityAnalysisFailedAt)
        XCTAssertEqual(analyzer.imageFileCallCount, 0)
    }

    func testAnalysisFailureDoesNotMarkContentSafeOrChecked() async throws {
        let referencePrimary = try insertMediaReference(primary: "failure", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg", isSensitive: true)
        let analyzer = FakeSensitiveMediaAnalyzer(imageFileResult: .failure(SensitiveMediaAnalysisTestError()))
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider(), dateProvider: { Date(timeIntervalSince1970: 200) })

        await service.analyzeMessageReference(primaryKey: referencePrimary)

        let realm = try WRealm.safe()
        let reference = try XCTUnwrap(realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: referencePrimary))
        XCTAssertTrue(reference.isSensitive)
        XCTAssertFalse(reference.isSensitiveChecked)
        XCTAssertEqual(reference.sensitivityAnalysisFailedAt, Date(timeIntervalSince1970: 200))
        XCTAssertEqual(reference.sensitivityAnalysisError, "analysis failed")
    }

    func testDuplicateAnalysisIsNotStartedForSamePrimaryKey() async throws {
        let referencePrimary = try insertMediaReference(primary: "duplicate", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg")
        let analyzer = FakeSensitiveMediaAnalyzer(imageFileResult: .success(true), delayNanoseconds: 200_000_000)
        let service = SensitiveMediaAnalysisService(analyzer: analyzer, fileProvider: FakeSensitiveMediaFileProvider())

        async let first: Void = service.analyzeMessageReference(primaryKey: referencePrimary)
        try await Task.sleep(nanoseconds: 20_000_000)
        async let second: Void = service.analyzeMessageReference(primaryKey: referencePrimary)
        _ = await (first, second)

        XCTAssertEqual(analyzer.imageFileCallCount, 1)
    }

    func testStartupScanPrimaryKeysAreDetachedFromRealmResults() throws {
        _ = try insertMediaReference(primary: "pending-startup-scan", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg")
        let checkedPrimary = try insertMediaReference(primary: "checked-startup-scan", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg")
        let sensitivePrimary = try insertMediaReference(primary: "sensitive-startup-scan", mimeType: "image/jpeg", mediaType: "image", fileExtension: "jpg", isSensitive: true)
        let realm = try WRealm.safe()

        try realm.write {
            realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: checkedPrimary)?.isSensitiveChecked = true
            realm.object(ofType: MessageReferenceStorageItem.self, forPrimaryKey: sensitivePrimary)?.isSensitiveChecked = false
        }

        let primaryKeys = MessageReferenceStorageItem.pendingSensitiveAnalysisPrimaryKeys(in: realm)
        let detachedIteration = expectation(description: "detached primary key iteration")
        var detachedPrimaryKeys: [String] = []

        DispatchQueue(label: "SensitiveMediaAnalysisServiceTests.detached-keys").async {
            detachedPrimaryKeys = primaryKeys.map { $0 }
            detachedIteration.fulfill()
        }

        wait(for: [detachedIteration], timeout: 1)
        XCTAssertEqual(detachedPrimaryKeys, ["pending-startup-scan"])
    }

    private func insertMediaReference(
        primary: String,
        mimeType: String,
        mediaType: String,
        fileExtension: String,
        isSensitive: Bool = false
    ) throws -> String {
        let fileURL = try temporaryFileURL(fileExtension: fileExtension)
        let message = MessageStorageItem()
        message.primary = "message-\(primary)"
        message.owner = "owner@example.com"
        message.opponent = "romeo@example.com"

        let reference = MessageReferenceStorageItem()
        reference.primary = primary
        reference.messageId = message.primary
        reference.owner = message.owner
        reference.jid = message.opponent
        reference.kind = .media
        reference.mimeType = mimeType
        reference.url = fileURL.absoluteString
        reference.metadata = [
            "localFileUri": fileURL.absoluteString,
            "media-type": mediaType
        ]
        reference.isSensitive = isSensitive
        reference.isSensitiveChecked = false

        let attachment = MessageMediaAttachmentStorageItem()
        attachment.primary = "attachment-\(primary)"
        attachment.owner = message.owner
        attachment.jid = message.opponent
        attachment.messagePrimary = message.primary
        attachment.archiveId = "archive-\(primary)"
        attachment.url = fileURL
        attachment.kind = mediaType == "video" ? .video : .image

        let realm = try WRealm.safe()
        try realm.write {
            realm.add(message, update: .modified)
            realm.add(reference, update: .modified)
            realm.add(attachment, update: .modified)
        }
        return primary
    }

    private func temporaryFileURL(fileExtension: String) throws -> URL {
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("SensitiveMediaAnalysisServiceTests-\(UUID().uuidString)")
            .appendingPathExtension(fileExtension)
        try Data([0]).write(to: url)
        tempURLs.append(url)
        return url
    }
}

