    func testOlderPagingChoosesGapRepairBeforeCrossingKnownGap() {
        let gap = RegularChatArchiveGap(
            olderRangeNewestArchiveId: "200",
            newerRangeOldestArchiveId: "400"
        )

        XCTAssertEqual(
            ChatArchiveGapPagingPolicy.loadDecision(
                direction: .older,
