@MainActor
final class LastChatsSwipeActionTests: XCTestCase {

    func testSwipeActionIconsResolve() {
        LastChatsViewController.swipeActionIconNames.forEach { iconName in
            XCTAssertNotNil(imageLiteral(iconName), "Expected swipe action icon to resolve: \(iconName)")
        }
    }

    func testSwipeActionAssetCacheReusesTemplatedImages() {
        LastChatsViewController.SwipeActionKind.allCases.forEach { kind in
            let first = LastChatsViewController.swipeActionDescriptor(for: kind).image
            let second = LastChatsViewController.swipeActionDescriptor(for: kind).image

            XCTAssertNotNil(first, "Expected cached image for \(kind)")
            XCTAssertTrue(first === second, "Expected repeated lookup to reuse cached image for \(kind)")
            XCTAssertEqual(first?.renderingMode, .alwaysTemplate)
        }
    }

    func testMutedAndUnmutedRowsSelectDifferentDescriptors() {
        let unmuted = makeDatasource(conversationType: .regular, isMute: false)
        let muted = makeDatasource(conversationType: .regular, isMute: true)

        XCTAssertEqual(
            LastChatsViewController.trailingSwipeActionKinds(for: unmuted, filter: .chats),
            [.archive, .delete, .mute, .block]
        )
        XCTAssertEqual(
            LastChatsViewController.trailingSwipeActionKinds(for: muted, filter: .chats),
            [.archive, .delete, .unmute, .block]
        )
        XCTAssertFalse(
            LastChatsViewController.swipeActionDescriptor(for: .mute).image ===
                LastChatsViewController.swipeActionDescriptor(for: .unmute).image
        )
    }

    func testArchivedAndNonArchivedTrailingActionOrderIsPreserved() {
        let item = makeDatasource(conversationType: .regular)

        XCTAssertEqual(
            LastChatsViewController.trailingSwipeActionKinds(for: item, filter: .chats),
            [.archive, .delete, .mute, .block]
        )
        XCTAssertEqual(
            LastChatsViewController.trailingSwipeActionKinds(for: item, filter: .archived),
            [.unarchive, .delete, .mute, .block]
        )
    }

    func testCallActionKindIsGatedByConversationType() {
        let direct = makeDatasource(conversationType: .regular)
        let group = makeDatasource(conversationType: .group)

        XCTAssertEqual(
            LastChatsViewController.leadingSwipeActionKinds(for: direct),
            [.pin, .call]
        )
        XCTAssertEqual(
            LastChatsViewController.leadingSwipeActionKinds(for: group),
            [.pin]
        )
    }

    func testBlockActionKindIsGatedByConversationType() {
        let direct = makeDatasource(conversationType: .regular)
        let saved = makeDatasource(conversationType: .saved)
        let notification = makeDatasource(conversationType: .notifications)

        XCTAssertTrue(LastChatsViewController.trailingSwipeActionKinds(for: direct, filter: .chats).contains(.block))
        XCTAssertFalse(LastChatsViewController.trailingSwipeActionKinds(for: saved, filter: .chats).contains(.block))
        XCTAssertFalse(LastChatsViewController.trailingSwipeActionKinds(for: notification, filter: .chats).contains(.block))
    }

    func testDirectChatsAllowCallAndBlockActions() {
        let directTypes: [ClientSynchronizationManager.ConversationType] = [
            .regular,
            .omemo,
            .omemo1,
            .axolotl
        ]

        directTypes.forEach { conversationType in
            let item = makeDatasource(conversationType: conversationType)

            XCTAssertTrue(LastChatsViewController.canShowCallAction(for: item))
            XCTAssertTrue(LastChatsViewController.canShowBlockAction(for: item))
        }
    }

    func testGroupAndChannelRowsAllowBlockButNotCall() {
        let groupRows: [ClientSynchronizationManager.ConversationType] = [
            .group,
            .channel
        ]

        groupRows.forEach { conversationType in
            let item = makeDatasource(conversationType: conversationType)

            XCTAssertFalse(LastChatsViewController.canShowCallAction(for: item))
            XCTAssertTrue(LastChatsViewController.canShowBlockAction(for: item))
        }
    }

    func testSavedNotificationAndSpecialRowsDoNotExposeNewActions() {
        let saved = makeDatasource(conversationType: .saved)
        let notification = makeDatasource(conversationType: .notifications)
        let contactRequest = makeDatasource(conversationType: .regular, specialMessageKind: .contact)
        let invite = makeDatasource(conversationType: .group, specialMessageKind: .invite)

        [saved, notification, contactRequest, invite].forEach { item in
            XCTAssertFalse(LastChatsViewController.canShowCallAction(for: item))
            XCTAssertFalse(LastChatsViewController.canShowBlockAction(for: item))
        }
    }

    func testReloadOnlyChangesDoNotRequireStructuralTableBatch() {
        let reloadOnly = ChangesWithIndexPath(
            inserts: [],
            deletes: [],
            replaces: [IndexPath(row: 0, section: 0)],
            moves: []
        )
        let structural = ChangesWithIndexPath(
            inserts: [IndexPath(row: 1, section: 0)],
            deletes: [],
            replaces: [IndexPath(row: 0, section: 0)],
            moves: []
        )

        XCTAssertFalse(LastChatsViewController.hasStructuralTableChanges(reloadOnly))
        XCTAssertTrue(LastChatsViewController.hasStructuralTableChanges(structural))
    }

    func testRowUpdatePolicyClassifiesRenderedContentChangesAsContentOnly() {
        let base = makeDatasource(conversationType: .regular)
        let contentOnlyRows = [
            makeDatasource(conversationType: .regular, message: "Updated preview"),
            makeDatasource(conversationType: .regular, date: Date(timeIntervalSince1970: 1_711_283_260)),
            makeDatasource(conversationType: .regular, state: .read),
            makeDatasource(conversationType: .regular, isMute: true),
            makeDatasource(conversationType: .regular, status: .online),
            makeDatasource(conversationType: .regular, unread: 5),
            makeDatasource(conversationType: .regular, hasUnreadMention: true),
            makeDatasource(conversationType: .regular, isPinned: true),
            makeDatasource(conversationType: .regular, avatarUrl: "avatar-key-1"),
            makeDatasource(conversationType: .regular, username: "Juliet"),
            makeDatasource(conversationType: .regular, isVerificationActionRequired: true)
        ]

        contentOnlyRows.forEach { item in
            XCTAssertEqual(
                LastChatsRowUpdatePolicy.classify(old: base, new: item),
                .contentOnly
            )
        }
    }

    func testRowUpdatePolicyClassifiesTypingTextAsContentOnly() {
        let base = makeDatasource(conversationType: .regular, message: "Hello")
        let typing = makeDatasource(conversationType: .regular, message: "typing...")

        XCTAssertEqual(
            LastChatsRowUpdatePolicy.classify(old: base, new: typing),
            .contentOnly
        )
    }

    func testRowUpdatePolicyKeepsStructuralChangesAsReloads() {
        let base = makeDatasource(conversationType: .regular)

        XCTAssertEqual(
            LastChatsRowUpdatePolicy.classify(
                old: base,
                new: makeDatasource(conversationType: .regular),
                oldShowsSkeleton: true,
                newShowsSkeleton: false
            ),
            .structuralReload
        )
        XCTAssertEqual(
            LastChatsRowUpdatePolicy.classify(
                old: base,
                new: makeDatasource(conversationType: .omemo)
            ),
            .structuralReload
        )
        XCTAssertEqual(
            LastChatsRowUpdatePolicy.classify(
                old: base,
                new: makeDatasource(conversationType: .regular, specialMessageKind: .contact)
            ),
            .structuralReload
        )
        XCTAssertEqual(
            LastChatsRowUpdatePolicy.classify(
                old: makeDatasource(conversationType: .regular, specialMessageKind: .contact),
                new: makeDatasource(conversationType: .regular, specialMessageKind: .invite)
            ),
            .structuralReload
        )
    }

    func testLastChatsDatasourceCompareContentTracksRenderedFields() {
        let base = makeDatasource(conversationType: .regular)
        let redTitle = NSAttributedString(
            string: "Romeo",
            attributes: [.foregroundColor: UIColor.red]
        )
        let blueTitle = NSAttributedString(
            string: "Romeo",
            attributes: [.foregroundColor: UIColor.blue]
        )
        let avatar = AvatarStructItem(
            jid: "romeo@example.com",
            owner: "owner@example.com",
            name: "Romeo",
            url: "avatar-key-1",
            isGroup: false,
            uuid: "avatar-uuid"
        )

        XCTAssertFalse(LastChatsViewController.Datasource.compareContent(
            base,
            makeDatasource(conversationType: .regular, isVerificationActionRequired: true)
        ))
        XCTAssertFalse(LastChatsViewController.Datasource.compareContent(
            base,
            makeDatasource(conversationType: .regular, specialMessageKind: .contact)
        ))
        XCTAssertFalse(LastChatsViewController.Datasource.compareContent(
            makeDatasource(conversationType: .regular, specialMessageKind: .contact),
            makeDatasource(conversationType: .regular, specialMessageKind: .contact, avatars: [avatar])
        ))
        XCTAssertFalse(LastChatsViewController.Datasource.compareContent(
            makeDatasource(conversationType: .regular, attributedUsername: redTitle),
            makeDatasource(conversationType: .regular, attributedUsername: blueTitle)
        ))
    }

    private func makeDatasource(
        jid: String = "romeo@example.com",
        conversationType: ClientSynchronizationManager.ConversationType,
        specialMessageKind: LastChatsViewController.SpecialMessageKind = .none,
        username: String = "Romeo",
        attributedUsername: NSAttributedString? = nil,
        message: String = "Hello",
        date: Date? = Date(timeIntervalSince1970: 1_711_283_200),
        state: MessageStorageItem.MessageSendingState? = nil,
        isMute: Bool = false,
        status: ResourceStatus = .offline,
        unread: Int = 0,
        hasUnreadMention: Bool = false,
        isPinned: Bool = false,
        avatarUrl: String? = nil,
        isVerificationActionRequired: Bool = false,
        avatars: [AvatarStructItem] = []
    ) -> LastChatsViewController.Datasource {
        LastChatsViewController.Datasource(
            jid: jid,
            owner: "owner@example.com",
            username: username,
            attributedUsername: attributedUsername,
            message: message,
            date: date,
            state: state,
            isMute: isMute,
            isSynced: true,
            status: status,
            entity: conversationType == .regular || conversationType.isEncrypted ? .contact : .groupchat,
            conversationType: conversationType,
            unread: unread,
            unreadString: nil,
            hasUnreadMention: hasUnreadMention,
            color: .clear,
            isDraft: false,
            hasAttachment: false,
            userNickname: nil,
            isSystemMessage: false,
            isPinned: isPinned,
            subRequest: false,
            isEncrypted: conversationType.isEncrypted,
            avatarUrl: avatarUrl,
            hasErrorInChat: false,
            updateTS: 0,
            isVerificationActionRequired: isVerificationActionRequired,
            specialMessageKind: specialMessageKind,
            avatars: avatars
        )
    }
}

final class ChatListEmptyStateTests: XCTestCase {

    func testMainChatsEmptyShowsEmptyStateWhenNotLoadingAndSearchInactive() {
        XCTAssertTrue(
            LastChatsViewController.shouldShowEmptyState(
                filter: .chats,
                isLoading: false,
                isSearchActive: false,
                datasourceIsEmpty: true
            )
        )
    }

    func testNonEmptyDatasourceHidesEmptyState() {
